import type { Claim } from './types';
export type { Claim, ClaimStatus } from './types';

/**
 * Every number and physical statement used on the page, with its source. `status` is set from the
 * independent verification log (docs/verification.md): auditors who had not seen this site opened each
 * cited source and checked the statement against it. Where an auditor found a discrepancy, the statement
 * below is the corrected one and `note` records what changed.
 */
export const CLAIMS: Claim[] = [
  // ───────────── section 1: single neuron ─────────────
  { id: 'quasistatic', section: 1, statement: 'At EEG frequencies the head is a purely resistive (quasi-static) volume conductor: for brain tissue with σ ≈ 0.3 S/m and relative permittivity ~10⁵ the ratio of capacitive to ohmic current at 100 Hz is 2πfε/σ ≈ 2×10⁻³, and in vivo cortical impedance is frequency-independent and predicted by a purely resistive conductor.', refs: ['hamalainen1993', 'logothetis2007', 'malmivuo1995', 'plonsey1967'], status: 'verified' },
  { id: 'monopole', section: 1, statement: 'The potential of a point current source I in an infinite homogeneous conductor of conductivity σ is Φ = I / (4πσr) (Malmivuo & Plonsey eq. 8.7).', refs: ['malmivuo1995'], status: 'verified' },
  { id: 'dipole', section: 1, statement: 'The potential of a current dipole of moment p is Φ = p cosθ / (4πσr²) (eq. 8.15); the dipole field falls as 1/r² whereas the monopole field falls as 1/r.', refs: ['malmivuo1995'], status: 'verified' },
  { id: 'sigma-gray', section: 1, statement: 'Gray-matter conductivity: 0.33 S/m is the classical modeling value (0.3 S/m for brain tissue in Hämäläinen et al.; 0.333 S/m for gray matter in the Ramon et al. finite-element table). The 2019 meta-analysis gave a weighted mean of 0.47 ± 0.24 S/m across 16 gray-matter studies (66 values; reported range 0.06–2.47 S/m), revised to 0.38 ± 0.16 S/m in its 2021 correction.', value: 0.33, units: 'S/m', range: [0.06, 2.47], refs: ['mccann2019', 'mccann2021', 'ramon2006', 'hamalainen1993'], status: 'verified', note: 'Audit: Hämäläinen’s 0.3 S/m is a brain-tissue value used in a quasi-static validity estimate; the 2021 correction (0.38 S/m) was added after the audit flagged it.' },
  { id: 'epsc', section: 1, statement: 'A unitary connection between thick-tufted layer-5 pyramidal cells (rat somatosensory slices) produces an excitatory postsynaptic potential of 1.3 ± 1.1 mV (range 0.15–5.5 mV) with an inferred quantal peak conductance of 1.5–5.5 nS (mean 3 nS) at −60 mV.', refs: ['markram1997'], status: 'verified' },
  { id: 'cell-current', section: 1, statement: 'Order-of-magnitude current used as the slider default: a burst-envelope dipole of 0.4–0.9 pA·m over an apical trunk of ~0.4–0.6 mm gives ~1–2 nA of net membrane current; for comparison, a single synaptic contact with a quantal conductance of 1.5–5.5 nS passes on the order of 100–300 pA at a ~60 mV driving force.', value: 1, units: 'nA', refs: ['murakami2006', 'galloni2020', 'markram1997'], status: 'derived', note: 'Derived from the cited moment, trunk length and conductance; none of the sources states the current directly. Murakami & Okada’s envelope arises from a somatically stimulated burst, not a synaptic one.' },
  { id: 'dipole-length', section: 1, statement: 'Mean apical trunk length (soma to main bifurcation) of layer-5 pyramidal neurons is 409 ± 64 µm in mouse V1 and 313 ± 65 µm in V2m; in the thick-tufted (Hay et al. 2011) model used in the same study the main bifurcation lies ~620 µm from the soma. The slider default of 500 µm lies in this range.', value: 500, units: 'µm', range: [313, 620], refs: ['galloni2020'], status: 'verified', note: 'Corrected after audit: an earlier version quoted 685–885 µm, which is the model’s dendritic Ca²⁺ hot zone, not the trunk length.' },
  { id: 'spike-noise-floor', section: 1, statement: 'Neuropixels silicon probes have a noise floor of about 5 µV rms in the action-potential band (5.1 ± 0.6 µV in saline; 5.5–6.6 µV rms across the four probe configurations) and 8–13 µV rms in the LFP band.', value: 5, units: 'µV rms', range: [5.1, 6.6], refs: ['jun2017'], status: 'verified', note: 'Corrected after audit: LFP-band noise given as a range (8–13 µV) rather than “about 9 µV”.' },
  { id: 'cortex-layers', section: 1, statement: 'Human cerebral cortex is 1 to 4.5 mm thick with an overall average of about 2.5 mm (histological values quoted by Fischl & Dale). In human temporal cortex layer 4 ends about 1.6 mm below the pia and the gray/white border lies at about 2.8 mm; layer 5 begins about 1.5 mm below the pia, and human layer-5 pyramidal neurons were recorded 1.5 to 2.2 mm below it. The drawings place the cell body 1.6 mm below the surface.', value: 1.6, units: 'mm', range: [1.5, 2.2], refs: ['fischl2000', 'mohan2015', 'beaulieu2018'], status: 'verified', note: 'Audit: the thickness figures are histological values quoted in Fischl & Dale’s introduction, not their MRI result, and the soma depths are now taken from Beaulieu-Laroche et al. (1.5–2.2 mm); a Kalmbach et al. 2021 figure that the auditor could not access was dropped.' },
  { id: 'henze-50um', section: 1, statement: 'In urethane-anaesthetised rat hippocampal CA1 in vivo, extracellular spikes recorded within 50 µm of the soma are ≥ 60 µV (units as large as ~600 µV were observed).', value: 60, units: 'µV', refs: ['henze2000'], status: 'verified' },
  { id: 'henze-140um', section: 1, statement: 'Beyond about 140 µm from the soma no extracellular spike could be distinguished from background noise even with spike-triggered averaging.', value: 140, units: 'µm', refs: ['henze2000'], status: 'verified' },
  { id: 'spike-decay', section: 1, statement: 'Modeled extracellular spike amplitude decays as 1/rⁿ with 1 ≤ n ≤ 2 close to the soma and n ≥ 2 far away, and spikes are low-pass filtered with distance.', refs: ['pettersen2008'], status: 'verified' },
  { id: 'lfp-reach', section: 1, statement: 'For uncorrelated synaptic activity the local field potential represents cells within a radius of a few hundred micrometers; with correlated activity the generating region grows to the spatial extent of the correlated activity.', refs: ['linden2011'], status: 'verified', note: 'Verified from the abstract (full text paywalled).' },
  { id: 'single-cell-moment', section: 1, statement: 'In realistic compartmental models a layer-5 pyramidal cell produces a current dipole of 0.41–0.90 pA·m (directed away from the pia) during the slow envelope of a burst, with spike components of −0.78 to +2.97 pA·m; a layer-2/3 pyramidal cell gives 0.29 pA·m (envelope) and 0.47 pA·m (spike).', value: 0.5, units: 'pA·m', range: [0.41, 0.9], refs: ['murakami2006'], status: 'verified' },
  { id: 'psp-moment', section: 1, statement: 'A single postsynaptic potential produces a current dipole of about 20 fA·m, so about a million simultaneously active synapses are needed for a typical 10 nA·m evoked-response dipole.', value: 20, units: 'fA·m', refs: ['hamalainen1993'], status: 'verified' },
  { id: 'ephaptic', section: 1, statement: 'Applied fields of ≤ 0.5 mV/mm modulate slow-oscillation network activity in cortical slices (sine-wave fields of 1–4 mV/mm also significant), and weak fields entrain the spiking of individual cortical neurons while polarizing the soma by less than 0.5 mV, most effectively below 8 Hz.', value: 0.5, units: 'mV/mm', refs: ['frohlich2010', 'anastassiou2011'], status: 'verified', note: 'Corrected after audit: the Anastassiou full text is paywalled, so only its abstract-level statements are used; the earlier 0.74 mV/mm figure was dropped.' },
  // ───────────── section 2: populations ─────────────
  { id: 'superposition', section: 2, statement: 'Extracellular potentials from multiple current sinks and sources combine linearly by superposition (for an ohmic, homogeneous medium); all volume conductors in bioelectricity are assumed linear, consistent with experiment.', refs: ['buzsaki2012', 'malmivuo1995'], status: 'verified' },
  { id: 'variances-add', section: 2, statement: 'In population models of the local field potential, uncorrelated single-cell contributions add in variance (so amplitude grows as √N) whereas fully correlated contributions add in amplitude (∝ N); with correlated input the population signal no longer saturates with population size.', refs: ['leski2013', 'linden2011'], status: 'verified', note: 'The √N / N exponents are the arithmetic consequence of the source’s “variances add” versus “amplitudes add”.' },
  { id: 'open-closed', section: 2, statement: 'Spatial alignment of neurons and temporal synchrony of their currents are the two most important determinants of extracellular field strength; pyramidal cells with long, thick apical dendrites oriented perpendicular to the cortical surface generate strong dipoles (open fields), whereas spherically symmetric cells tend toward closed fields that cancel at a distance, and populations of stellate cells may sum to less than the linear sum of their dipoles because of their variable dendritic geometry.', refs: ['buzsaki2012', 'murakami2006', 'kirschstein2009'], status: 'verified' },
  { id: 'psp-dominate', section: 2, statement: 'Synaptic currents last tens of milliseconds, overlap in time and are often the most important source of extracellular current; the strongest action-potential fields last under 2 ms and nearby neurons rarely spike synchronously within such windows (although synchronous spiking can still contribute to high-frequency components), and a propagating action potential is a current quadrupole whose field falls off as 1/r³, faster than a dipole’s 1/r².', refs: ['buzsaki2012', 'hamalainen1993'], status: 'verified', note: 'Duration and quadrupole statements are from Hämäläinen et al.; the high-frequency caveat was added after the audit.' },
  { id: 'cells-for-10nam', section: 2, statement: 'A typical MEG/EEG source has an equivalent current dipole of about 10 nA·m, caused by the synchronous activity of probably tens of thousands of neurons; modeled pyramidal-cell bursts become detectable when 10,000–50,000 cells are synchronously active.', value: 10, units: 'nA·m', range: [10000, 50000], refs: ['hamalainen1993', 'murakami2006'], status: 'verified' },
  { id: 'neuron-density', section: 2, statement: 'Rockel, Hiorns & Powell counted ~110 neurons in a 30-µm-wide strip through the cortical depth (750 µm² of surface), i.e. about 147,000 neurons under 1 mm² of cortical surface (primate binocular area 17 excepted, ~2.5×); a 2013 stereological replication confirmed the uniformity, while Herculano-Houzel et al. report up to three-fold variation across primate species.', value: 147000, units: 'neurons/mm²', refs: ['rockel1980', 'herculano2008', 'carlo2013'], status: 'verified', note: 'Verified from abstracts; the 147,000/mm² conversion is stated by Herculano-Houzel et al.' },
  { id: 'pyramidal-fraction', section: 2, statement: 'About one in five neocortical neurons is GABAergic (inhibitory) across many areas and species, so roughly 80% are excitatory (glutamatergic) neurons, of which pyramidal cells are the main class.', value: 0.8, refs: ['sahara2012'], status: 'verified' },
  { id: 'tao-area', section: 2, statement: 'With simultaneous scalp and intracranial EEG in 16 temporal-lobe-epilepsy patients, intracranial spikes involving < 6 cm² of cortex were never seen on the scalp, only 10% of spikes with < 10 cm² produced scalp spikes, and 90% of spikes with > 10 cm² did; synchronous (or at least temporally overlapping) activation of 10–20 cm² of gyral cortex was common.', value: 10, units: 'cm²', range: [6, 20], refs: ['tao2005'], status: 'verified' },
  { id: 'area-rule', section: 2, statement: 'Rule of thumb from the tutorial literature: roughly 6–10 cm² of contiguous, synchronously active cortex is needed for a potential recognizable at the scalp, and scalp EEG is a spatiotemporally smoothed version of the local field potential integrated over 10 cm² or more.', range: [6, 10], units: 'cm²', refs: ['nunez2019', 'buzsaki2012'], status: 'verified', note: 'Split from the Tao et al. claim after the audit noted that these secondary sources do not contain Tao’s percentages.' },
  { id: 'glia-slow', section: 2, statement: 'Glial membrane-potential changes can contribute to extracellular potentials, but the glial syncytium is thought to contribute mainly to slow and infraslow (< 0.1 Hz) field patterns.', value: 0.1, units: 'Hz', refs: ['buzsaki2012'], status: 'verified', note: 'Corrected after audit: “only” → “mainly” (the source hedges with “may”).' },
  { id: 'ca-spike-moment', section: 2, statement: 'Dendritic Ca²⁺ spikes are large (10–50 mV) and long-lasting, so under some circumstances their share of extracellular events can be substantial; separately, in single-cell models the Na⁺ action-potential component of a layer-5 pyramidal cell’s dipole ranges from −0.78 to 2.97 pA·m across cells, versus 0.41–0.90 pA·m for the slow burst envelope.', value: 2.97, units: 'pA·m', refs: ['buzsaki2012', 'murakami2006'], status: 'verified', note: 'Corrected after audit: the 2.97 pA·m figure is a somatic action potential in the model, not a dendritic Ca²⁺ spike.' },
  { id: 'sync-thalamic', section: 2, statement: 'During relaxed wakefulness the EEG shows alpha (8–13 Hz) activity on which the thalamus is a strong influence; two thalamic cellular mechanisms, high-threshold burst firing in a subset of thalamocortical neurons and the interconnection of that subset by gap junctions, combine to generate locally synchronized alpha activity, and the same machinery yields theta (2–7 Hz) when the thalamocortical neurons are less depolarized.', refs: ['hughes2005'], status: 'verified', note: 'Audit: supported by the abstract.' },
  { id: 'sync-inhibition', section: 2, statement: 'Gamma oscillations (30–90 Hz) are generated by networks of inhibitory interneurons acting through GABA-A synapses; perisomatic inhibition by fast-spiking basket cells is the key synchronizing ingredient, a network of mutually connected interneurons needs only mutual inhibition, the GABA-A time constant and enough drive to oscillate at gamma, and (citing Lytton & Sejnowski’s 1991 modeling) perisomatic inhibitory potentials synchronize neurons substantially more effectively than dendritic excitatory ones.', refs: ['buzsakiwang2012'], status: 'verified', note: 'Audit: wording aligned to the source (“substantially more effective”, a cited modeling result).' },
  { id: 'sync-waves', section: 2, statement: 'Cortical activity also propagates as traveling waves at two scales carried by distinct axon populations: mesoscopic waves within one cortical area at speeds consistent with unmyelinated layer 2/3 horizontal fibers (0.1–0.8 m/s), and macroscopic waves spanning centimeters at 1–10 m/s, within the range of myelinated white-matter conduction; human ECoG sleep-spindle waves cluster at 2–5 m/s.', refs: ['muller2018'], status: 'verified', note: 'Audit: the 2–5 m/s figure applies to sleep-spindle waves only; an earlier wording that extended it to alpha waves was removed.' },
  { id: 'oscillations-synchrony', section: 2, statement: 'Mammalian forebrain networks show oscillatory bands spanning about 0.05–500 Hz; the period of an oscillation is constrained by the size of the neuronal pool engaged in each cycle, with very large networks recruited during slow oscillations.', refs: ['buzsaki2004'], status: 'verified' },
  { id: 'inhibitory-contrib', section: 2, statement: 'Inhibitory (GABA-A) currents, often assumed to add little, can generate substantial transmembrane currents when the membrane is depolarized in actively spiking neurons; spike-triggered unitary field potentials in human and monkey cortex indicate that the LFP reflects primarily inhibitory-neuron activity, inferred from timing and polarity (amplitudes of inhibitory and excitatory unitary fields were similar).', refs: ['buzsaki2012', 'telenczuk2017'], status: 'verified', note: 'Conditions added after the audit.' },
  { id: 'orientation', section: 2, statement: 'EEG sensitivity depends only weakly on source orientation (median ratio of weakest to strongest orientation 0.63; 95% of cortical locations above 0.42), whereas MEG is nearly blind to one orientation (median 0.06) and insensitive to radial sources.', value: 0.63, refs: ['ahlfors2010'], status: 'verified' },
  // ───────────── section 3: head layers ─────────────
  { id: 'mccann-meta', section: 3, statement: 'Meta-analysis of reported human head-tissue conductivities (weighted means, 2019): scalp 0.41 S/m, whole skull 0.016 S/m (0.02 in the abstract), spongy bone 0.050, compact bone 0.0046 S/m, brain-to-skull ratio 50.4 (reported range 17.9–290). Its 2021 correction revised the brain values to CSF 1.74, gray matter 0.38 and white matter 0.15 S/m (originally 1.71, 0.47 and 0.22).', refs: ['mccann2019', 'mccann2021'], status: 'verified', note: 'Corrected after audit: the 2021 correction was added and its values adopted.' },
  { id: 'sigma-csf', section: 3, statement: 'Human cerebrospinal fluid conductivity measured in 7 patients is 1.79 S/m at 37 °C (1.45 S/m at 25 °C) across 10 Hz–10 kHz; the meta-analytic weighted mean is 1.74 S/m (2021 correction; 1.71 in the 2019 paper).', value: 1.79, units: 'S/m', range: [1.0, 2.51], refs: ['baumann1997', 'mccann2019', 'mccann2021'], status: 'verified' },
  { id: 'sigma-skull', section: 3, statement: 'Whole-skull conductivity: about 0.015 S/m from in vivo and in vitro measurements (brain:skull ≈ 15:1); meta-analytic weighted mean 0.016 S/m (reported as 0.02 ± 0.02 in the abstract); live skull layers 16–41 mS/m (spongiform), 5.4–7.2 mS/m (outer compact) and 2.8–10.2 mS/m (inner compact); skull pieces removed at surgery gave 32–80 mS/m.', value: 0.015, units: 'S/m', range: [0.0028, 0.08], refs: ['oostendorp2000', 'mccann2019', 'akhtari2002', 'hoekema2003'], status: 'verified' },
  { id: 'skull-brain-ratio', section: 3, statement: 'A brain-to-skull conductivity ratio of 80 was the commonly used value in source localization; in vivo estimates give about 15 (current injection, Oostendorp et al.), 25 ± 7 (range 18–34) from simultaneous scalp and subdural recordings, and 20–50 from electrical impedance tomography; the meta-analytic weighted mean is 50.4 ± 39 (10 studies).', value: 25, range: [15, 80], refs: ['lai2005', 'goncalves2003', 'oostendorp2000', 'mccann2019'], status: 'verified', note: 'Corrected after audit: the attribution of the value 80 to Rush & Driscoll (1968) was removed because it does not appear in the accessible text of the cited sources.' },
  { id: 'sigma-scalp', section: 3, statement: 'Scalp conductivity: meta-analytic weighted mean 0.41 S/m (realistic values 0.25–0.435 S/m after excluding outliers); 0.435 S/m in the Ramon et al. finite-element table; the Nunez et al. four-sphere model assumes scalp and brain equal.', value: 0.41, units: 'S/m', range: [0.25, 0.435], refs: ['mccann2019', 'ramon2006', 'nunez2019'], status: 'verified' },
  { id: 'sigma-dura', section: 3, statement: 'Dura mater conductivity used in a dura-inclusive finite-element head model is 0.06 S/m (literature bounds 0.02–0.1 S/m, about 0.04× CSF); the meta-analysis found insufficient data for dura (its single tabulated value is 0.461 S/m). Including the dura layer reduced simulated scalp potentials by about 20% (up to 40% at the peak location).', value: 0.06, units: 'S/m', range: [0.02, 0.1], refs: ['ramon2014', 'mccann2019'], status: 'verified', note: 'Ramon et al.’s own abstract misprints the dura/CSF values; the Methods/Table values are used here.' },
  { id: 'thickness-skull', section: 3, statement: 'Mean calvarial thickness across 40 frontal, parietal and occipital sites in 281 dry skulls is 6.32 mm (site means 5.3–7.5 mm); age was not a significant predictor.', value: 6.32, units: 'mm', range: [5.3, 7.5], refs: ['moreira2006'], status: 'verified' },
  { id: 'thickness-scalp', section: 3, statement: 'Normal full scalp thickness at the vertex on ultrasound is about 5–6 mm (stated as the normal range in a two-patient clinical case report); the Nunez et al. four-sphere model implies a 6 mm scalp shell (radii 8.6 and 9.2 cm).', value: 5.5, units: 'mm', range: [5, 6], refs: ['khalil2024', 'nunez2019'], status: 'partially', note: 'Low-confidence source for the normative value; no normative study was located.' },
  { id: 'thickness-csf', section: 3, statement: 'The Nunez et al. four-sphere model uses radii of 8.0 and 8.1 cm for brain and CSF, i.e. a 1 mm CSF layer; the occipital CSF layer thins by about 30% when a subject moves from prone to supine, raising occipital EEG power for spatially incoherent high-frequency activity by about 80% on average (several-fold in some subjects).', value: 1, units: 'mm', refs: ['nunez2019', 'rice2013'], status: 'verified', note: 'Corrected after audit: “high-frequency” restored; radii verified in the open preprint of Nunez et al.' },
  { id: 'thickness-dura', section: 3, statement: 'Cranial dura thickness measured at autopsy over the petrous apex (skull base; 19 of 20 decedents analyzed) averages 0.36 mm (0.27–0.46 mm, SD 0.16 mm); convexity dura under the EEG cap was not measured, so the value is an order of magnitude.', value: 0.36, units: 'mm', range: [0.27, 0.46], refs: ['fam2018'], status: 'verified' },
  { id: 'csf-shunt', section: 3, statement: 'The highly conductive CSF channels (shunts) current, lowering peak cortical current density; head models that omit the CSF layer underestimate the half-sensitivity volume by 20% (MRI-based) to 45% (CT-based), and a model without CSF performed worst in source localization.', refs: ['wendel2008', 'ramon2006'], status: 'verified' },
  { id: 'spatial-lowpass', section: 3, statement: 'The scalp EEG is spatially low-pass filtered by the poorly conducting skull: a four-sphere model predicts that electrodes within 10–12 cm can appear correlated purely through volume conduction, and measured scalp spatial spectra fall off faster than at the pia because of smearing by dura, skull and scalp.', refs: ['srinivasan1998ieee', 'freeman2003'], status: 'verified' },
  { id: 'sphere-model', section: 3, statement: 'A standard analytic EEG forward model is the concentric-sphere head (brain, CSF, skull, scalp with radii 8.0, 8.1, 8.6, 9.2 cm in Nunez et al.); exact series solutions for multilayer spheres are given by de Munck & Peters (1993); Berg & Scherg (1994) give a fast three-dipole approximation, which Zhang (1995) extended to multilayer anisotropic spheres.', refs: ['nunez2019', 'demunck1993', 'berg1994', 'zhang1995'], status: 'verified', note: 'Corrected after audit: Zhang (1995) is an extension of the Berg & Scherg approximation, not an exact series.' },
  { id: 'exterior-potential', section: 3, statement: 'With air treated as a perfect insulator, no current leaves the head and the interior solution is unchanged; the potential in the air is the solution of Laplace’s equation that equals the scalp potential on the surface and vanishes at infinity, so each spherical-harmonic term of degree l continues outward as (R/r)^(l+1), the finer the pattern the faster. For the default source of section 3 (scalp half-width 2.2 cm) the potential on the axis falls to 70% of its scalp value 0.5 cm above the skin, to half at about 1 cm and to a quarter at 3 cm.', refs: ['jackson1999', 'hallez2007'], status: 'derived', note: 'Standard exterior boundary-value problem (exterior solutions of Laplace’s equation: Jackson; zero normal current into the air as the EEG boundary condition: Hallez et al.). The percentages are computed by the page’s own solver (exteriorPotential in src/physics/sphere.ts); the auditor’s independent Legendre calculation for a 2.2 cm half-width pattern gave 71 / 53 / 21%, with the 3 cm value the most shape-sensitive. Wires, the electrode itself and the rest of the body are ignored. Audit: Nunez et al. 2019 was replaced by Hallez et al. 2007, which states the boundary condition.' },
  { id: 'brain-radius', section: 3, statement: 'The Nunez et al. four-sphere model’s brain radius is 8.0 cm.', value: 8.0, units: 'cm', refs: ['nunez2019'], status: 'verified' },
  { id: 'ecog-vs-eeg', section: 3, statement: 'For an isolated macrocolumn-scale cortical dipole the expected cortical-to-scalp potential ratio is about 50–100, while measured spontaneous ECoG/EEG ratios are typically 2–5 (as expected for large synchronous dipole sheets); a textbook gives ~100 µV on the scalp versus 1–2 mV on the brain surface; simultaneous invasive and scalp recordings show invasive signal quality (brain signal relative to blink artifact) 20 to more than 100 times better; in a 144,000-dipole simulation the standard deviation of potentials falls from 22.8 µV on the cortex to 7.7 µV at the outer dura, 5.2 µV at the outer skull and 4.5 µV on the scalp.', range: [2, 100], refs: ['nunez2019', 'malmivuo1995', 'ball2009', 'ramon2014'], status: 'verified' },
  { id: 'eeg-amplitude', section: 3, statement: 'Scalp EEG amplitudes are of the order of 10–100 µV (a textbook puts the scalp EEG at about 100 µV).', value: 50, units: 'µV', range: [10, 100], refs: ['chi2010', 'malmivuo1995'], status: 'verified' },
  // ───────────── section 7: noise ─────────────
  { id: 'alpha-source-chain', section: 7, statement: 'The 20 µV alpha rhythm used in sections 4 and 7 is not an independent choice: in the section 3 head (radial source 2 mm below the cortical surface, default layer thicknesses and conductivities) the page’s own solver gives 0.54 µV at the scalp per nA·m, so 20 µV corresponds to an equivalent dipole of about 37 nA·m, roughly four times the 10 nA·m that Hämäläinen et al. call typical; at 0.29 to 0.90 pA·m per cell (0.5 pA·m used) that is about 4 to 13 × 10⁴ perfectly synchronous pyramidal cells, or 740,000 with a tenth in step, the same order as the tens of thousands of cells associated with a typical source.', value: 37, units: 'nA·m', refs: ['malmivuo1995', 'murakami2006', 'hamalainen1993'], status: 'derived', note: 'Audit: arithmetic confirmed; the 0.54 µV per nA·m is the page’s own four-layer result, not a literature value; Nunez et al. 2019 was dropped from the sources because it supplies none of these numbers; the per-cell range and the comparison with the typical 10 nA·m were added.' },
  { id: 'emg-band', section: 7, statement: 'Surface EMG from striated muscle spans about 20–300 Hz; contamination of resting EEG begins at about 20 Hz (from ~12 Hz with voluntary contraction); muscle artifact at temporal electrodes can reach ~100 µV whereas genuine high-frequency (gamma) neural activity at the scalp can be under 1 µV.', value: 100, units: 'µV', range: [20, 300], refs: ['muthukumaraswamy2013', 'goncharova2003'], status: 'verified' },
  { id: 'emg-level', section: 7, statement: 'Modeling choice: 10 µV rms of muscle noise in the 20–300 Hz band for a relaxed subject at a mid-scalp site, with 100 µV as the clenched-jaw value at a temporal site. Measured support: muscle activity at temporal EEG electrodes can reach about 100 µV against neural gamma below 1 µV; even at central electrodes in resting subjects, scalp EEG above 20 Hz is mostly muscle: Muthukumaraswamy’s reading of Whitham et al. gives about 5 times more power at 40 Hz and 10 times at 80 Hz than under paralysis, and Whitham et al. report 10- to 200-fold differences above 20 Hz; in Huigen et al.’s surface-electrode measurements, resting muscle added negligibly to electrode noise.', value: 10, units: 'µV rms', range: [0, 100], refs: ['muthukumaraswamy2013', 'whitham2007', 'huigen2002'], status: 'assumption', note: 'The relaxed-subject level of 10 µV rms is a chosen value: no source gives an rms figure for a relaxed subject at a mid-scalp site. Audit: measured statements supported; attributions made explicit.' },
  { id: 'emg-topography', section: 7, statement: 'Frontalis and temporalis EMG has a broad spectrum from 0 to > 200 Hz, peaking at 20–30 Hz frontally and 40–80 Hz temporally; even a 15%-of-maximum contraction produces EMG detectable near the vertex above 12 Hz in averaged data (above 8 Hz in some individuals); contamination is greatest at the periphery of the scalp.', range: [20, 80], refs: ['goncharova2003'], status: 'verified' },
  { id: 'blink-amplitude', section: 7, statement: 'Ocular artifact amplitude is generally many times greater than the EEG; uncorrected blinks are typically 100–200 µV at frontal channels, and practical ERP pipelines detect them with ±50–100 µV thresholds on a bipolar eye channel (with ±200 µV absolute and 100–150 µV moving-window thresholds for other large artifacts).', value: 150, units: 'µV', range: [100, 200], refs: ['luck2022', 'jiang2019', 'ronca2024'], status: 'verified', note: 'Corrected after audit: the amplitude now rests on Luck ch. 8 §8.3 (“typically 100–200 µV”) rather than on rejection thresholds.' },
  { id: 'blink-rate', section: 7, statement: 'Eye blinks occur about 12–18 times per minute, with spectral content mainly below ~15 Hz, strongest at frontal electrodes.', value: 15, units: 'per minute', range: [12, 18], refs: ['ronca2024'], status: 'verified', note: 'The review states the blink rate without citing a primary source.' },
  { id: 'common-mode', section: 7, statement: 'The 50/60 Hz common-mode voltage on the body is about 1 mV peak-to-peak with a small isolated battery-powered amplifier, about 10 mV p-p in a typical non-isolated set-up, and up to ~200 mV p-p in a multichannel system with large isolation capacitance; the interference current through the body is typically ~0.5 µA p-p, with ten-fold higher currents found regularly.', value: 10, units: 'mV', range: [1, 200], refs: ['mettingvanrijn1990'], status: 'verified' },
  { id: 'potential-divider', section: 7, statement: 'Differences in electrode impedance or amplifier input impedance convert common-mode voltage into a differential signal (the potential-divider effect): 10 mV p-p common-mode with 20 MΩ input impedance, 20 kΩ electrodes and 50% differences in both gives ~10 µV p-p of mains interference; the usual electrodes show ~20 kΩ at 50 Hz with ~50% inter-electrode differences.', value: 10, units: 'µV', refs: ['mettingvanrijn1990'], status: 'verified' },
  { id: 'cmrr-customary', section: 7, statement: 'A common-mode rejection ratio of 80–90 dB was customary for differential biopotential amplifiers (1990); a driven-right-leg circuit usually reduces common-mode voltage by a further 10–50 dB; 1–10 µV peak-to-peak of interference (under 1% of an ECG) is considered acceptable.', value: 90, units: 'dB', range: [80, 90], refs: ['mettingvanrijn1990'], status: 'verified' },
  { id: 'ads1299', section: 7, statement: 'The ADS1299 EEG front end specifies 1 µV peak-to-peak typical input-referred noise (0.14 µV rms at 250 samples/s, gain 24, 65 Hz bandwidth; 1.35 µV p-p maximum), CMRR of −110 dB minimum at 50/60 Hz, 1000 MΩ DC input impedance (lead-off detection off), 20 pF input capacitance and ±300 pA input bias current.', value: 0.14, units: 'µV rms', refs: ['ads1299'], status: 'verified' },
  { id: 'thermal-noise', section: 7, statement: 'Thermal (Johnson–Nyquist) noise of a resistance R at temperature T over bandwidth Δf has mean-square voltage 4kTRΔf, i.e. v_rms = √(4kTRΔf); for 10 kΩ, 310 K and 100 Hz this is ≈ 0.13 µV rms.', refs: ['nyquist1928'], status: 'verified', note: 'The numerical example is derived from the formula; the auditor confirmed the arithmetic.' },
  { id: 'skin-noise', section: 7, statement: 'Surface-electrode noise on skin is 1–20 µV rms depending on skin treatment and subject, originates mainly at the electrolyte–skin interface (electrodes face-to-face in gel give < 1 µV rms once stabilized), is considerably higher than the thermal noise of the electrode impedance, and scales inversely with the square root of electrode area.', range: [1, 20], units: 'µV rms', refs: ['huigen2002'], status: 'verified' },
  { id: 'averaging', section: 7, statement: 'Averaging N trials improves the signal-to-noise ratio of an event-related potential in proportion to √N (noise falls as SD/√N); typical components are a few microvolts (error-related negativity difference 5–15 µV, lateralised readiness potential 1–4 µV) while single-trial noise is much larger than the signal.', refs: ['luck2022', 'boudewyn2018'], status: 'verified', note: 'The √N statement was verified in Luck’s open textbook (ch. 6 §6.7); the component amplitudes were verified in the Boudewyn et al. author manuscript (eScholarship) after the auditor could not access it.' },
  { id: 'motion-artifact', section: 7, statement: 'No satisfying quantitative model exists for the triboelectric charge generated by friction at the electrode–skin interface (transversal motion is modeled to first order as a change in coupling impedance); capacitive non-contact electrodes can need more than 10–15 s to recover after a motion-induced overload; mains current coupled into cables (10 nA p-p with 20 kΩ electrodes and 50% differences in current and impedance) gives ~200 µV p-p of interference.', refs: ['chi2010', 'mettingvanrijn1990'], status: 'verified', note: 'Reworded after audit.' },
  { id: 'running-artifact', section: 7, statement: 'Eight subjects wearing a 248-channel cap stood, walked (0.8 and 1.25 m/s) and ran (1.9 m/s) on a treadmill. Before artifact removal the grand mean EEG power in the 1.5–8.5 Hz band was 3.45, 4.43, 5.49 and 65.01 µV²/Hz in these four conditions. Running raised power across a broad spectrum and especially at the step frequency and its harmonics; its signals could be an order of magnitude larger before artifact removal than after, and removal reduced the artifact without eliminating it (31.7 µV²/Hz remained). Step frequencies were about 1.8–2.0 Hz walking at 1.25 m/s and 2.6–2.8 Hz running.', range: [1.8, 2.8], units: 'Hz', refs: ['gwin2010'], status: 'verified', note: 'Checked by hand against the full text (Results; captions of figures 3, 4 and 7). The step frequencies are read from figure 4.' },
  { id: 'running-artifact-size', section: 7, statement: 'The gait artifacts of section 7 are the excess over standing in that band: running, (65.01 − 3.45) µV²/Hz over 7 Hz ≈ 431 µV², about 21 µV rms, at a 2.7 Hz step frequency; walking at 1.25 m/s, (5.49 − 3.45) µV²/Hz over 7 Hz ≈ 14 µV², about 3.8 µV rms, at a 1.9 Hz step frequency. Each is placed at its step frequency and 2nd and 3rd harmonics with amplitudes in the ratio 1 : 0.6 : 0.35 (the harmonic shape is a modeling choice). The measured value is a grand mean across subjects, so one electrode on one person can see more or less.', value: 20.8, units: 'µV rms', refs: ['gwin2010'], status: 'derived' },
  { id: 'head-movement-artifacts', section: 7, statement: 'Seven healthy adults wearing a 14-channel consumer headset (Emotiv EPOC, 128 Hz) shook, nodded and rolled the head and clenched the jaw (prolonged and intermittent clenches mimicking chewing) for 30 s each, staying still in between. In the thesis figures, nodding and shaking give bursts of about ±50–150 µV at frontal electrodes (F8, FC5), rolling the head gives slow baseline swings of about 100–300 µV lasting seconds (F3), and jaw clenching gives bursts of about ±50–100 µV (F7), against background EEG of about ±15–20 µV. Many movement artifacts appear as large baseline shifts; chewing can also add tongue (glossokinetic) potentials, often with muscle activity.', refs: ['oregan2013'], status: 'partially', note: 'Checked by hand against the thesis (sections 2.9.1 and 6.5.3, table 2.1, figures 4.2–4.5). The text gives no amplitudes: the µV values are read from the figure axes, for one person and electrode each, and a consumer headset may pick up more movement artifact than a gel cap.' },
  { id: 'movement-artifact-shapes', section: 7, statement: 'Modeling choices for the chewing, nodding and rolling artifacts of section 7, sized to the readings in claim head-movement-artifacts: chewing as bursts of 20–225 Hz muscle noise at 30 µV rms lasting 0.3 s, one every 0.8 s; nodding as a 1 Hz swing of 50 µV amplitude plus neck-muscle bursts of 15 µV rms at the same rate; rolling the head as slow swings of 120 µV at 0.3 Hz plus 40 µV at 0.7 Hz. No cited source gives the chewing or nodding rate.', refs: [], status: 'assumption' },
  // ───────────── section 8: electrodes ─────────────
  { id: 'chi-table', section: 8, statement: 'Measured coupling impedances (differential pair of closely spaced electrodes on the resting forearm; skin preparation not reported): wet Ag/AgCl gel electrode ≈ 350 kΩ ∥ 25 nF; dry metal plate ≈ 1.3 MΩ ∥ 12 nF; thin-film insulated electrode ≈ 550 MΩ ∥ 220 pF; non-contact through a cotton shirt ≈ 305 MΩ ∥ 34 pF.', refs: ['chi2010'], status: 'partially', note: 'Electrode area is not stated in the table; the site uses the values as per-cm² references for scalp electrodes (a modeling assumption).' },
  { id: 'abrasion', section: 8, statement: 'The traditional way to obtain low-noise contact is to abrade the skin to a contact resistance of 5–10 kΩ; EEG practice historically required < 5 kΩ, and unabraded saline-sponge electrodes measure about 10 kΩ.', range: [5, 10], units: 'kΩ', refs: ['chi2010', 'ferree2001'], status: 'verified' },
  { id: 'rosell', section: 8, statement: 'For gel-coated but otherwise unprepared skin over 1 cm² (thorax, leg and forehead sites), the 1 Hz skin impedance ranged from 10 kΩ to 1 MΩ across ten sites on ten subjects, falling to ~220 Ω at 100 kHz and ~120 Ω at 1 MHz.', range: [10e3, 1e6], units: 'Ω·cm²', refs: ['rosell1988'], status: 'verified' },
  { id: 'area-scaling', section: 8, statement: 'Contact impedance falls with effective contact area: in a finite-element model of a 1 cm × 1 cm dry electrode the 20 Hz impedance is 17.6 kΩ at full contact and about 60 kΩ (data point; ~51 kΩ by the fitted regression) when only 25% of the area makes contact, the authors naming skin pores and hair as the reasons a plate’s whole surface is not in contact; electrode noise scales as 1/√area.', value: 17.6, units: 'kΩ', refs: ['cardu2012', 'huigen2002'], status: 'verified' },
  { id: 'hair', section: 8, statement: 'Occipital scalp hair density is 124–200 hairs/cm² (65–85 follicular units/cm², 1.0–1.4 mm apart); in Caucasian women pigmented scalp hairs average ~57 µm and white hairs ~68 µm in diameter.', range: [57, 68], units: 'µm', refs: ['jimenez1999', 'vanneste2004'], status: 'verified', note: 'Reworded after audit (the two diameters are pigmented vs white hair means, not a population range).' },
  { id: 'hair-permittivity', section: 8, statement: 'No measured relative permittivity for a hair/air layer under an electrode was located; the model treats the gap as air (εr = 1) by default and exposes εr as a slider.', value: 1, refs: [], status: 'assumption' },
  { id: 'noncontact-cap', section: 8, statement: 'Non-contact electrodes are nominally described as coupling through tens of picofarads (with a non-negligible resistive component in practice); insulated electrodes in direct skin contact couple through ~300 pF (Alizadeh-Taheri et al. 1996, as reported by Chi et al.) to several nanofarads; a custom amplifier reached 50 TΩ ∥ 60 fF input impedance and worked with coupling capacitances as low as 0.5 pF; a practical active electrode has ~5 pF input capacitance, which forms a divider with the coupling capacitance unless actively shielded.', refs: ['chi2010', 'chi2011', 'alizadeh1996'], status: 'verified', note: 'Corrected after audit: the 300 pF figure is attributed to Alizadeh-Taheri et al. (1996), not Taheri et al. (1994).' },
  { id: 'haired-scalp-wet', section: 8, statement: 'Raising electrode coupling resistance lowers noise only when R exceeds 1/(ωC); for the low coupling capacitance of a gapped electrode this threshold becomes exceedingly large, which is why the 2010 review concluded that research EEG over haired scalp still required wet electrodes.', refs: ['chi2010'], status: 'verified', note: 'The November 2026 citation audit noted that this is a 2010 assessment of gapped (non-contact) electrodes, not a present-day rule for every dry design; the page now dates it and cites later dry electrodes that reach the scalp (claim dry-through-hair).' },
  { id: 'ferree', section: 8, statement: 'Modern EEG amplifiers have input impedances of order 200 MΩ ∥ 10 pF; raising scalp-electrode impedance from < 10 kΩ (abraded skin) to 40 kΩ (intact skin) produced no significant amplitude change in any EEG band, 60 Hz noise was nearly independent of impedance and mismatch (≈8% non-significant increase), and by analysis impedances up to 200 kΩ give < 0.1% amplitude error.', refs: ['ferree2001'], status: 'verified', note: 'Corrected after audit to match the published abstract (< 10 kΩ; 60 Hz nearly independent of mismatch).' },
  { id: 'kappenman', section: 8, statement: 'With a high-input-impedance active-electrode system, sites left at their natural 10–190 kΩ needed about 35 trials to reach 80% power for a P3 effect versus about 12 trials for sites abraded to < 5 kΩ; the extra noise was concentrated at low frequencies (skin potentials; the spectra in their figure 4 diverge mainly below about 5 Hz and are similar above) and worse in a warm, humid room.', range: [12, 35], units: 'trials', refs: ['kappenman2010'], status: 'verified', note: 'Second audit: the “below 5 Hz” figure is read from their figure 4 rather than stated in the text, so it is now attributed to the figure.' },
  { id: 'dry-vs-wet-time', section: 8, statement: 'Dry electrodes start with higher impedance but can become comparable to wet electrodes after a few minutes as sweat accumulates; in one study (Lin et al. 2011, as reported by Lopez-Gordo et al.) wet-electrode impedance deteriorated from 5 to 15 kΩ over 5 hours after gel application while dry-electrode impedance stayed constant.', refs: ['chi2010', 'lopezgordo2014'], status: 'verified', note: 'Both statements are secondary reports.' },
  { id: 'searle', section: 8, statement: 'In a direct comparison, shielded dry and insulating electrodes picked up 40 dB and 34 dB less interference from non-stationary electric fields than wet electrodes; their motion artifacts were higher than wet electrodes at the start of trials but lower by 8.2 dB and 6.8 dB on average by the end.', refs: ['searle2000'], status: 'verified' },
  { id: 'fingered', section: 8, statement: 'Hair-penetrating fingered dry electrodes have been reported at 14–55 kΩ per finger (TiN) versus ~10 MΩ per finger for another dry sensor, and high skin-contact impedance results in much larger motion artifacts with dry sensors.', refs: ['chi2010'], status: 'verified' },
  { id: 'consumer-electrodes', section: 8, statement: 'A systematic review of low-cost consumer EEG headsets states that most use dry electrodes, naming the InteraXon Muse (dry electrodes at FPz, AF7, AF8, TP9 and TP10) and the single-channel NeuroSky MindWave (dry forehead electrode with an ear-clip reference); the Dreem sleep headband uses five dry silicone electrodes, the occipital ones carrying protrusions that reach the scalp through hair, and Bitbrain’s Diadem uses 12 dry sensors with no gel; by contrast the Emotiv EPOC X uses saline-based sensors and the Emotiv Insight semi-dry polymer sensors.', refs: ['larocco2020', 'arnal2020', 'bitbraindiadem', 'emotivepocx', 'emotivinsight'], status: 'verified', note: 'Audit: supported; the through-hair protrusions are on the Dreem’s occipital electrodes. Manufacturer pages are not peer reviewed.' },
  { id: 'electrode-noise-levels', section: 8, statement: 'Modeling choice for the traces: electrode–skin noise of 1.5 µV rms (abraded, gelled skin), 4 µV (gel on unprepared skin), 8 µV (dry plate) and 8 µV (plate over hair), with a 1/f spectrum and 1/√area scaling. Huigen et al. measured 1–20 µV rms for gelled electrodes depending on skin treatment, with noise scaling as 1/√(electrode area); the 1/f character of that noise is attributed to Huigen et al. by the Chi et al. review; Kappenman & Luck found noise elevated at low frequencies at unabraded, high-impedance sites, with spectra similar at higher frequencies. The values for dry plates and plates over hair are extrapolations.', refs: ['huigen2002', 'chi2010', 'kappenman2010'], status: 'assumption', note: 'The ordering (abraded < gel < dry) follows the cited dependence on skin treatment; the specific values are chosen, not measured. Audit: the 1–20 µV range, its dependence on skin treatment and the 1/√area scaling are in Huigen et al.’s abstract; the 1/f spectrum is only corroborated through Chi et al. 2010; the earlier “below 5 Hz” wording was a reading of Kappenman & Luck’s figure 4, not a stated number, and was removed.' },
  { id: 'amp-current-noise', section: 8, statement: 'An amplifier’s input current noise drives the electrode and amplifier input impedances in parallel and appears as voltage noise iₙ·|Zₑ ∥ Zᵢₙ|; a research non-contact amplifier reached 0.05 fA/√Hz current noise and 200 nV/√Hz voltage noise, both at 1 Hz, with an input impedance of 60 fF ∥ 50 TΩ. Commercial EEG front ends such as the TI ADS1299 do not specify a current-noise density (300 pA typical input bias current), so the model default of 1 fA/√Hz is a modeling choice.', value: 1, units: 'fA/√Hz', refs: ['chi2011', 'ads1299'], status: 'verified', note: 'Audit: both Chi et al. figures appear verbatim in the abstract, and “at 1 Hz” qualifies both (the earlier wording attached it only to the voltage noise). The 1 fA/√Hz default is an assumption.' },
  // ───────────── section 9: dimensionality ─────────────
  { id: 'iivanainen-components', section: 9, statement: 'Generalized spatial-frequency analysis of a realistic four-compartment head model: about 110 spatial-frequency components capture 99% of the scalp-EEG topography energy of the most superficial sources (versus ~280 for on-scalp MEG), requiring an EEG sensor spacing of ~2.6 cm (at least ~120 sensors); in a homogeneous single-shell model without skull or CSF the median count rises from 80 to about 290.', value: 110, refs: ['iivanainen2021'], status: 'verified', note: 'Corrected after audit (on-scalp MEG ~280; the no-skull comparison is the single-shell median 291 vs 80).' },
  { id: 'iivanainen-eigen', section: 9, statement: 'For independent, identically distributed cortical sources, 26 eigencomponents explain 99% of scalp-EEG variance (88 for on-scalp MEG); with noise, about 20 EEG samples suffice for 90% of the variance at low noise, while at high noise even 400 samples explain only ~80%. In the preprint, for a small motor-cortex region of interest only 8 EEG components had SNR above 1 with white sensor noise (4 with brain-background noise).', value: 26, range: [4, 26], refs: ['iivanainen2021', 'iivanainen2019'], status: 'verified', note: 'Corrected after audit: published value 26 (preprint 25); the region-of-interest figures appear only in the preprint and are attributed to it.' },
  { id: 'spatial-nyquist', section: 9, statement: 'Characterizing the full range of spatial frequencies in scalp EEG (spherical-harmonic degree up to about 7 on a ~9 cm head) requires a minimum of 128 sensors at just under 3 cm spacing; 32 or fewer channels is a sparse montage (the authors call the estimate preliminary).', value: 128, refs: ['srinivasan1998nyquist'], status: 'verified' },
  { id: 'freeman-spectra', section: 9, statement: 'Scalp spatial power spectra measured with a 3 mm-pitch linear array peak at 0.1–0.4 cycles/cm (wavelengths of 2.5–10 cm), suggesting ~1 cm optimal spacing; a finite-element study by overlapping authors argues for a practical Nyquist of 3 cycles/cm (~3 mm spacing).', range: [0.1, 3], units: 'cycles/cm', refs: ['freeman2003', 'ramon2009'], status: 'verified' },
  { id: 'ryynanen', section: 9, statement: 'In a three-layer spherical head model, electrode arrays up to 256 channels improved inverse cortical-potential estimates only at low realistic noise; the advantage of dense arrays shrinks as noise grows, though in clinical environments at least 64 electrodes is always beneficial. Clinically, interictal-spike sources were significantly closer to the lesion with 63 than with 31 electrodes in 9 of 14 patients, rising to 11 of 14 with 123.', range: [64, 256], refs: ['ryynanen2004', 'lantz2003'], status: 'verified' },
  { id: 'ica-dipolar', section: 9, statement: 'Decomposing 71-channel EEG from 13 subjects, the best independent-component algorithm (AMICA) yielded on average 34 of 71 components (48%) with near-dipolar scalp maps (under 10% residual variance).', value: 34, refs: ['delorme2012'], status: 'verified' },
  { id: 'inverse-illposed', section: 9, statement: 'The distributed EEG inverse problem is underdetermined: the number of candidate source locations is far larger than the number of electrodes (p ≫ N), with electrode counts usually below 100.', refs: ['grech2008'], status: 'verified' },
  { id: 'cortical-neurons', section: 9, statement: 'The adult (male) human brain contains 86 ± 8 billion neurons, of which 19% (about 16 billion) are in the cerebral cortex.', value: 1.6e10, refs: ['azevedo2009'], status: 'verified' },
  { id: 'itr-2002', section: 9, statement: 'As of 2002 the best brain–computer interfaces had maximum information transfer rates of 10–25 bits per minute.', value: 25, units: 'bits/min', refs: ['wolpaw2002'], status: 'verified' },
  { id: 'itr-ssvep', section: 9, statement: 'A 40-target steady-state visual evoked potential (SSVEP) speller reached information transfer rates up to 5.32 bits/s (~319 bits/min); a later 40-class speller averaged 325 bits/min cue-guided and 199 bits/min in free spelling.', value: 5.32, units: 'bits/s', refs: ['chen2015', 'nakanishi2018'], status: 'verified' },
  { id: 'mi-classes', section: 4, statement: 'Imagined movements of the left hand, right hand, foot (both feet in the competition data) and tongue produce distinguishable sensorimotor-rhythm changes: hand-area mu desynchronizes during hand imagery but is enhanced during foot and tongue imagery. These are the four motor-imagery classes of BCI Competition IV dataset 2a.', refs: ['pfurtscheller2006', 'tangermann2012'], status: 'verified', note: 'Audit: supported; wording aligned to the sources.' },
  { id: 'motor-map', section: 4, statement: 'The hand area of primary motor cortex lies on a knob of the precentral gyrus, and the mouth region of motor cortex has been localized by stereotaxic coordinates. The patch centers drawn in section 4 are the site’s own approximate coordinates, chosen to lie on that hand knob (±37, −25, 58 mm in MNI space), on the paracentral lobule next to the midline for the feet (0, −30, 72 mm) and on the ventral precentral mouth region (±55, −8, 36 mm), converted to the fsaverage head frame with MNE-Python. The right-shoulder patch sits on the left hemisphere 14 mm nearer the midline, 7 mm further back and 9 mm higher than the hand patch, the offset of the shoulder peak from the index-finger peak in the motor cortex row of Grafton et al.’s table 1 (individual analysis, Talairach coordinates: shoulder 20, −32, 57 mm; finger 34, −25, 48 mm; six subjects tracking a target with the right arm, positron emission tomography); they report shoulder responses as the most dorsomedial, with extensive overlap between segments.', refs: ['yousry1997', 'fox2001', 'grafton1993'], status: 'assumption', note: 'Audit: only the hand-knob location was verifiable from the sources; the coordinates are modeling choices, not values taken from them, and two sources that could not be checked (Homan et al. 1987; Penfield & Boldrey 1937) were dropped.' },
  { id: 'dof-control', section: 9, statement: 'People learned two-dimensional cursor control from scalp sensorimotor rhythms, and four adults learned simultaneous control of three independent EEG signals (one per dimension, from 3–4 electrodes), reaching targets in a virtual cube in 56–93% of trials, the first report of three-dimensional EEG control.', value: 3, units: 'dimensions', refs: ['wolpaw2004', 'mcfarland2010'], status: 'verified', note: 'Corrected after audit: the claim no longer asserts that three is the most dimensions ever demonstrated.' },
  { id: 'kinematics-chance', section: 9, statement: 'Linear-regression reconstruction of limb kinematics from low-frequency scalp EEG produced positive correlations that were not above the chance level estimated by randomly pairing velocity profiles with EEG from other trials (and with synthetic random data).', refs: ['antelis2013'], status: 'verified' },
  { id: 'fsaverage-bem', section: 4, statement: 'FreeSurfer’s fsaverage template (a high-resolution average cortical surface built by spherical intersubject registration) is available to MNE-Python through mne.datasets.fetch_fsaverage (downloaded on first use) together with a three-layer boundary-element head model (inner skull, outer skull, scalp; ico-4 surfaces of 5120 triangles each; file fsaverage-5120-5120-5120-bem-sol.fif), fiducials, a head–MRI transform and an ico-5 cortical source space; mne.make_bem_model defaults to conductivity = (0.3, 0.006, 0.3), i.e. brain and scalp 0.3 S/m and skull 0.006 S/m.', refs: ['mnefsaverage', 'mnebemmodel', 'mnefsaveragesrc', 'gramfort2014', 'fischl1999'], status: 'verified', note: 'Corrected after audit: files are fetched, not bundled; the file list is verified in the MNE source (mne/datasets/_fsaverage/base.py) and the layer/triangle description in Gramfort et al. 2014.' },
  { id: 'mne-bem', section: 4, statement: 'MNE computes EEG forward solutions (gain matrices) for single- or three-compartment boundary-element models using the linear collocation method of Mosher, Leahy & Lewis (1999) combined with the isolated-skull approach of Hämäläinen & Sarvas (1989); a three-compartment model is required when EEG data are present.', refs: ['gramfort2014', 'mosher1999', 'hamalainen1989'], status: 'verified', note: 'Corrected after audit: attribution of the collocation method moved to Mosher et al.; the 2013 Frontiers paper was dropped from this claim.' },
  { id: 'montages', section: 4, statement: 'The five-percent (10–5) system of Oostenveld & Praamstra (2001) extends the International 10–20 and 10–10 systems to 345 electrode positions. MNE-Python provides template montages through mne.channels.make_standard_montage, including 10–20/10–10/10–5 layouts fitted to fsaverage (fsaverage_1020/1010/1005, MNE ≥ 1.13) and the BioSemi 64/128/256 layouts (biosemi64/128/256); the available names are listed by mne.channels.get_builtin_montages().', refs: ['oostenveld2001', 'mnemontage'], status: 'verified', note: 'Corrected after audit: attribution limited to the 10–5 extension; montage names updated to MNE 1.13 (the analysis uses fsaverage_1020 and fsaverage_1005).' },
  { id: 'svd-method', section: 4, statement: 'With independent, identically distributed sources of rms moment q and white sensor noise of rms n, the scalp covariance is q²LLᵀ + n²I; its eigenvectors are the left singular vectors of the lead field L and component k has signal variance q²sₖ², so it exceeds the noise when sₖq > n. The fraction of signal variance carried by the first K components is Σₖ≤ᴋ sₖ² / Σ sₖ² (the eigencomponent criterion of Iivanainen et al.).', refs: ['iivanainen2021'], status: 'derived', note: 'Standard linear algebra applied to the lead field; the variance-fraction criterion follows Iivanainen et al.' },
  { id: 'svd-counts', section: 9, statement: 'Computed here (scripts/leadfield_svd.py, MNE-Python 1.13, fsaverage BEM, 20,484 fixed-orientation cortical sources, average reference): the number of lead-field components carrying 99% of the scalp variance of IID sources is 15 with 19 electrodes and 21–23 with 64 to 1,833 electrodes (90%: 7); restricting to the 14,001 sources inside a fitted sphere gives 16–17 for the realistic head and 15–16 for the sphere (64 electrodes and up).', value: 22, range: [15, 23], refs: [], status: 'derived', note: 'Our own computation; regenerate with the script. Depends on the IID-source assumption and the three-layer model without CSF.' },
  // ───────────── section 10: delays ─────────────
  { id: 'erd-timecourse', section: 10, statement: 'Before a self-paced finger movement the upper-alpha (mu) rhythm over the contralateral sensorimotor area begins to desynchronize about 1.75 ± 0.61 s before movement onset, beta power is attenuated in the 2.0 to 0.5 s before it, and after a brisk movement the beta rhythm recovers and shows a short-lasting synchronization within 1 s. In cue-paced left/right hand motor imagery the cue-triggered motor-cortex activation starts about 300 ms after the cue and single-trial discrimination peaks about 1 s after it; the original Graz imagery BCI returned its classification within 1.5 s, and adaptive autoregressive classification was expected to carry a delay of around 1 s.', value: 1, units: 's', refs: ['pfurtscheller1989', 'stancak1996', 'pfurtscheller1996', 'pfurtscheller2010', 'pfurtscheller1997', 'pfurtscheller1998'], status: 'verified', note: 'Audit: all figures supported; the 1989 paper says “upper alpha components” (called mu here), and the 300 ms and 1 s cue-paced figures are the hybrid-BCI paper’s summary of earlier Graz data. The model’s defaults (fade begins 0.3 s after the intention, complete at 1 s) follow the cue-paced figures.' },
  { id: 'spectral-window', section: 10, statement: 'A periodogram of N samples cannot resolve spectral details closer than 1/N cycles per sample (1/T in hertz for a record of duration T), and its variance is high and does not fall as the record lengthens; averaging the periodograms of L shorter segments (the Bartlett method; Welch’s method with windowed, overlapping segments) reduces the variance by a factor L and the resolution by the same factor, so the choice of window trades resolution against variance.', refs: ['stoica2005', 'welch1967'], status: 'verified', note: 'Audit: supported (the 1/T restatement in hertz is the site’s unit conversion).' },
  { id: 'bci-windows', section: 10, statement: 'In the fastest flicker (SSVEP) spellers each selection takes 1 s, 0.5 s of stimulation plus 0.5 s for the gaze shift (60 characters/min, up to 5.32 bits/s), or 0.8 s with 0.3 s of stimulation (75 characters/min); the EEG epoch starts 0.14 s after the stimulus because of the visual pathway’s latency. The sensorimotor-rhythm BCI that reached three-dimensional control recomputed its spectrum every 50 ms from the previous 400 ms of EEG, and cue-paced motor-imagery competition data allotted 4 s of imagery per trial. Self-paced movement intention can be detected from the readiness potential about 500 ms before the movement.', value: 1, units: 's', refs: ['chen2015', 'nakanishi2018', 'mcfarland2010', 'tangermann2012', 'lew2012'], status: 'partially', note: 'Audit: the 0.5 s stimulation, 5.32 bits/s, 50 ms / 400 ms, 4 s and 500 ms figures were confirmed; the 0.5 s gaze shift, 60 characters/min and 0.14 s offset (Chen et al., Table 1 and Fig. 1C legends) and the 0.3 s stimulation, 0.8 s and 75 characters/min (Nakanishi et al., Section II.B.2) rest on the research agent’s reading of the full texts, which the auditor could not open.' },
  { id: 'p300-timing', section: 10, statement: 'The P300 peaks about 300 ms after an infrequent target stimulus (measured as the largest positive peak in a window such as 250 to 500 ms); in a row/column P300 speller with 100 ms flashes and 60 ms gaps, 15 sequences of 12 row and column flashes (30 flashes of each character) take 28.8 s per character, and the original Farwell–Donchin speller managed 2.3 characters per minute; P300 BCIs generally average several repetitions to raise accuracy, which slows them.', value: 300, units: 'ms', refs: ['fazelrezai2012', 'polich2007', 'farwell1988', 'nakanishi2018'], status: 'partially', note: 'Audit: the 300 ms, flash timings, 28.8 s and 2.3 characters/min are confirmed; the 250–500 ms measurement window rests on the research agent’s reading of Polich’s full text, which the auditor could not open; the averaging statement is from the discussion of Nakanishi et al. 2018.' },
  { id: 'readiness-potential', section: 10, statement: 'The early readiness potential (Bereitschaftspotential) begins about 2 s before a self-initiated movement and its steeper late phase about 400 ms before; in Libet’s experiment the onset of the readiness potential preceded the reported moment of conscious intention by about 350 ms for fully spontaneous acts (about 800 ms with some preplanning), and that reported moment lies only about 200 ms before the movement (as summarized by Schurger et al.).', value: 2, units: 's', refs: ['shibasaki2006', 'libet1983', 'schurger2021'], status: 'verified', note: 'Audit: supported; the 800 ms figure applies to series in which some acts were preplanned.' },
  { id: 'brain-background', section: 9, statement: 'Modeling choice: the brain’s own activity in the decoder’s band is taken as 10 µV rms per electrode by default (adjustable 1 to 30 µV), spatially correlated as independent cortical sources seen through the same lead field. The sources give only the whole signal: scalp EEG of 10–100 µV (Chi et al.) and about 100 µV on the scalp (Malmivuo & Plonsey), with no band-limited or rms figures and nothing on spatial correlation, so the in-band share and the correlation model are assumptions; 10 µV rms in a few-hertz band is at the pessimistic end of what those whole-signal figures allow.', value: 10, units: 'µV rms', range: [1, 30], refs: ['chi2010', 'malmivuo1995'], status: 'assumption', note: 'Audit (batch 12): both sources support the whole-signal amplitude (Chi 2010 section II; Malmivuo & Plonsey section 13.1) and nothing more; the default is flagged as pessimistic, and the slider spans the range.' },
  { id: 'window-samples', section: 9, statement: 'A band of width B observed for T seconds carries about 2BT independent numbers (Shannon’s 2TW), so a detector that knows the waveform gains about √(2BT) in amplitude SNR by averaging over the window: √6 ≈ 2.45 for a 3 Hz band over 1 s. This is the upper, coherent gain; an energy detector that reads band power without knowing the phase gains about √(BT) on power SNR. The periodogram’s resolution of 1/T and its variance, which does not fall with record length without averaging, are the spectral-estimation side of the same fact.', value: 2.45, refs: ['shannon1949', 'stoica2005', 'welch1967'], status: 'derived', note: 'Audit (batch 12): arithmetic right; the 2BT count is Shannon 1949 section II, and Stoica & Moses give the resolution (eq. 2.4.18) and the inconsistency of the periodogram (section 2.4.4), not the √(2BT) gain itself; the coherent-versus-energy-detector caveat was added at the auditor’s request.' },
  { id: 'mi-bitrate', section: 9, statement: 'Four-class motor imagery in BCI Competition IV dataset 2a reached a mean kappa of 0.57 for the winning algorithm, an accuracy of about 0.68, with 4 s of imagery per trial; Wolpaw’s information-transfer formula gives 0.58 bits per trial, about 0.15 bits/s of imagery time (about 0.07 bits/s over the whole 8 s trial). The kappa is the peak of a time course for the winning algorithm, not a typical user.', value: 0.15, units: 'bits/s', refs: ['tangermann2012', 'wolpaw2002'], status: 'derived', note: 'Audit (batch 12): kappa 0.57 confirmed (Tangermann 2012 section 7.5, table 3; Ang et al. report 0.569), the formula confirmed in Wolpaw 2002 figure 4; recomputed as 0.582 bits per trial, so 0.59 became 0.58, and the whole-trial rate and the peak-value caveat were added.' },
  { id: 'intracortical', section: 9, statement: 'For contrast, intracortical interfaces have reached 90 characters/min (handwriting, 94.1% raw accuracy), 62 words/min (speech, 9.1% word error on a 50-word vocabulary) and grid-task throughputs of 1.4–3.7 bits/s across three participants on a 6 × 6 grid (4.2 bits/s for one participant on a 9 × 9 grid).', refs: ['willett2021', 'willett2023', 'pandarinath2017'], status: 'verified' },
  // --- added with the section 9 rebuild, the section 4 subtitle check and the blink width (research topics 7 and 9) ---
  { id: 'area-sizes', section: 4, statement: 'Body-part areas of sensorimotor cortex differ in size, following innervation rather than body size: direct stimulation of the precentral gyrus in 100 awake patients found the hand and face/mouth zones proportionally much larger than their body volume, and the authors conclude that the tongue’s representation is at least as large as the hand’s; in primary somatosensory cortex the largest fingertip activation cluster per subject was 335–1340 mm² against 7.8–200 mm² for the foot (fMRI, six adults; the total fingertip-correlated area was (12 ± 5) cm²). Penfield and Boldrey’s original 1937 homunculus was scaled by length along the central sulcus, not by area (textbooks later read its proportions as areas), and that first version exaggerated the tongue, which Penfield corrected in 1950.', refs: ['roux2020', 'willoughby2021', 'catani2017', 'penfield1937'], status: 'verified', note: 'Corrected after audit (batch 13): the fingertip and foot figures are now like for like (largest single cluster), the tongue size is the authors’ conclusion, and the exaggerated tongue is the 1937 drawing’s, corrected in 1950 (Catani). Roux read from the accepted manuscript.' },
  { id: 'own-rhythm', section: 4, statement: 'Each sensorimotor area can carry its own rhythm: with subdural grids the presence and blocking of the 7–11 Hz mu rhythm were specific to the body part represented under each electrode; in magnetoencephalography (MEG) the movement-related suppression and rebound of the 20 Hz rhythm follow the finger, toe and mouth representations, while the 10 Hz component stays near the hand area; on the scalp, desynchronization appears over the hand area with finger movement in every subject and, less consistently, over the foot area with toe movement, which led the authors to propose that each area has its own rhythm. The rhythms mark idling cortex: they fall when the body part moves.', refs: ['arroyo1993', 'salmelin1995', 'pfurtscheller1997b'], status: 'verified', note: 'Corrected after audit (batch 13): the foot-area effect was harder to find, the 20 Hz result is from MEG, and the area-specific rhythm is the authors’ proposal; checked from the three abstracts.' },
  { id: 'blink-width', section: 7, statement: 'In 31 subjects (62-channel EEG, right-mastoid reference) the blink peak at FP1 averaged about 160 µV (subject means 84–306 µV) and the mean blink width at FP1 was 0.197 s (subject means 0.099–0.279 s); the paper does not define how width was measured.', value: 0.197, units: 's', range: [0.099, 0.279], refs: ['guttmannflury2025'], status: 'verified', note: 'Audit (batch 13): supported, including Table 3.' },
  { id: 'erd-depth', section: 9, statement: 'How much sensorimotor-rhythm power is lost during imagery: in 20 young adults the peak desynchronization at C3 (most reactive 3 Hz band within 7–35 Hz, chosen on the contraction task and mostly in the beta range) during kinesthetic imagery of a wrist contraction was 21–89% across subjects, mean about 52–54% (actual contraction 39–92%, mean about 69–72%); in nine subjects the most reactive mu band over the hand area opposite the imagined hand lost on average about 85% of its power (single subjects 54–99%). Both are trial-averaged values in a best band; the site takes 50% as typical.', value: 50, units: '%', range: [21, 99], refs: ['toriyama2018', 'pfurtscheller2006'], status: 'verified', note: 'Corrected after audit (batch 13): Toriyama’s most reactive band lay at or above 13 Hz for most participants and was chosen on the contraction task; all numbers confirmed (Toriyama’s computed from its Table 1; Pfurtscheller read from the author copy).' },
  { id: 'erd-detect', section: 9, statement: 'In the long-window approximation, the power of band-limited Gaussian noise of bandwidth B averaged over a time T has about 2BT degrees of freedom and fractional uncertainty 1/√(BT), whatever its level (the radiometer equation); a gamma distribution with shape BT approximates the estimate. Section 11 instead computes finite-window mean squared complex-envelope magnitude, retaining temporal covariance and correlated noise between the two decoded channels, and compares their powers after subtracting known noise baselines. The site takes B = 3 Hz, the width of the analysis band in which the measurements of claim erd-depth located the most reactive frequencies; for B = 3 Hz and T = 1 s the approximation gives ±58% (the exact value for an ideal band averaged over a 1 s boxcar is about ±53%, so the approximation is slightly pessimistic).', refs: ['condon2016', 'shannon1949', 'kay1998'], status: 'derived', note: 'Audit (batch 14): the radiometer equation and 2BT samples confirmed in Condon & Ransom section 3.6 (eqs. 3.153–3.154) and Shannon 1949; the gamma form and the arithmetic confirmed; the auditor computed the exact ±53% for BT = 3 (analytic and by simulation), added here. Kay 1998 not opened.' },
  { id: 'rhythm-fluctuation', section: 9, statement: 'Real rhythms fluctuate more than a Gaussian process of the same bandwidth: in 57 healthy adults at rest the coefficient of variation of alpha-band power across 4 s epochs was 0.58–0.76 (a stationary Gaussian rhythm in a 3 Hz band would give 0.29; part of the measured excess is slow drift over the 10 min recording), the scatter falling as the inverse square root of the amount of data averaged; in most subjects (13 of 16) alpha power bursts between high- and low-amplitude modes, a non-Gaussian fluctuation. The site’s model is therefore optimistic.', range: [0.58, 0.76], refs: ['maltez2004', 'freyer2009'], status: 'verified', note: 'Audit (batch 13): supported; Maltez checked from its abstract only; the drift and the 13 of 16 were added at the auditor’s suggestion.' },
  { id: 'window-accuracy', section: 9, statement: 'Accuracy grows with the window: classifying left- versus right-hand imagery in BCI Competition IV dataset 2a (9 subjects, common spatial patterns with cross-validated linear discriminant analysis), the median subject scored about 60% with 0.5 s windows (about 56–77% across subjects), 65% at 1 s, 71% at 2 s and 74% at 4 s (about 58–97%), read from the paper’s Figure 3. In a separate cursor task accuracy rose as trials lengthened from 1 to 4 s, and in an offline analysis of four Graz BCI users the information at the best classification time was 0.4–1.1 bits per trial, 1.25–3 s after imagery began, about 0.3–0.4 bits/s.', refs: ['miladinovic2024', 'mcfarland2003', 'schlogl2002'], status: 'verified', note: 'Corrected after audit (batch 13): the paper’s text ranges (55–70% and 75–85%) contradict its own Figure 3, so the figure’s values are given; the cursor task (McFarland 2003, abstract) and the four-user analysis (Schlögl 2002) are separate studies.' },
  { id: 'mi-overlap', section: 9, statement: 'The imagery classes are not independent: imagining one hand lowered the mu rhythm over both hemispheres in all nine subjects, more on the opposite side on average (opposite −85% and −87%, same side −72% and −65%), though not in every subject; foot or tongue imagery tended to raise the hand-area mu instead; one of the nine desynchronized every central site during all four tasks and had the lowest four-class kappa (0.30), and the authors note that tasks with very similar central desynchronization would be nearly impossible to tell apart, and that more than two mental states are very hard to discriminate with imagery-induced desynchronization alone. Group topographies of 33 untrained adults also showed bilateral mu desynchronization.', refs: ['pfurtscheller2006', 'mcfarland2000'], status: 'verified', note: 'Corrected after audit (batch 14): the ‘nearly impossible’ is the authors’ hypothetical, observed in one subject of nine as the hardest case (kappa 0.30), and contralateral dominance holds for the means, not every subject. The auditor also noticed that rows s7 to s9 of the source’s Table 2 duplicate rows s1 to s3. McFarland 2000 checked from the abstract.' },
  { id: 'task-limit', section: 9, statement: 'Combining four motor-imagery tasks and mental arithmetic into sets of 2 to 5 classes, information transfer rates in 3 subjects were 0.42–0.81 bits per trial and the best came from three-task sets, adding a fourth or fifth task did not help; the authors put the upper limit of different mental tasks for a BCI at three. These task-specific results do not establish a general upper bound on EEG control.', refs: ['obermaier2001', 'yong2015'], status: 'verified', note: 'Audit (batch 14): supported; Obermaier 2001 checked from its abstract only; Yong & Menon make the low-dimensional statement about BCIs in general, so the wording was widened.' },
  { id: 'bci-inefficiency', section: 9, statement: 'BCI control fails for an estimated 15–30% of users; one group puts the share of potential users whose accuracy misses the criterion at about 20% (its own 80 naive users averaged 74% ± 17% in their first feedback session, from chance to 100%), and a review puts the share not proficient with a typical BCI at about 20%; in 54 subjects, 53.7% (the average of two sessions) fell below 70% on two-class motor imagery.', range: [15, 30], units: '%', refs: ['vidaurre2010', 'blankertz2010', 'allison2010', 'lee2019'], status: 'verified', note: 'Corrected after audit (batch 14): the 20% in Blankertz 2010 is a background figure for potential users, not a result of its 80-subject sample; the 15–30% is stated for EEG-based BCIs generally; Lee 2019’s 53.7% averages two sessions.' },
  // --- section 11: electrode count (research topic 8) ---
  { id: 'snr-electrodes', section: 11, statement: 'Computed here (src/physics/control.ts): one patch read from N electrodes spread evenly over the layered sphere of section 3, against the brain’s background (independent radial dipoles over the cortex sphere, a radial variant of the random-dipole model, seen through the same head) and white electrode noise, has the matched-filter SNR² = tᵀC⁻¹t, which is also the SNR of the best linear unbiased estimate of its amplitude. It is solved exactly in electrode space up to 128 electrodes and per spherical-harmonic degree above that, the degrees finer than the array resolves (l > √N − 1, since degrees up to L hold (L+1)² coefficients) counted as noise; the two agree within 1% at 128 to 256 electrodes. With 1 µV of electrode noise and 10 µV of background, a 10 nA·m patch of 10 mm radius reaches 0.43 with 64 electrodes, 0.69 with 256 and 0.90 with 100,000, against 4.9, 10 and 197 with the electrode noise alone.', refs: ['kay1998', 'demunck1992'], status: 'derived', note: 'Audit (batch 15): the method is standard and the numbers internally consistent (√N scaling of the electrode-only values, all below the ceiling); Kay 1998 and the de Munck full text were not opened, and de Munck’s model has dipoles of every orientation, so the radial version is called a variant.' },
  { id: 'electrode-ceiling', section: 11, statement: 'Computed here: with the whole scalp potential known exactly, the head’s transfer cancels, because the patch and the background pass through the same head, and the SNR reaches a ceiling set by the background sources under the patch’s own footprint, SNR² = Q² Σ (2l+1) g_l² / β (g_l the disc’s smoothing per degree, β the background density in the site’s normalization). For 10 nA·m over a 10 mm radius against 10 µV of background the ceiling SNR is 0.99, and halving the radius doubles it. Grover & Venkatesh argue that with brain noise as the dominant noise source, the number of sensors at which localization stops improving could be quite high; in this model the approach to the ceiling is slow when the electrode noise is low.', refs: ['grover2017'], status: 'derived', note: 'Audit (batch 15): the derivation was confirmed (the factor 4π depends on how β is normalized); the auditor could not open Grover & Venkatesh, so the attributed statement was checked by hand afterward in the authors’ preprint (section III-B, caption of figure 7).' },
  { id: 'grover-nyquist', section: 11, statement: 'Re-deriving the spatial Nyquist analysis, Grover & Venkatesh estimate that capturing 99% of the scalp signal’s energy needs at least 289 to 361 sensors (578 for the 289-sensor case with twofold oversampling), and in noiseless simulations source resolution kept improving up to 6,252 sensors; 10,000 electrodes on the head sit about 3 mm apart.', range: [289, 361], refs: ['grover2017'], status: 'verified', note: 'Audit (batch 14): supported against the authors’ May 2016 preprint; the published text was not accessible.' },
  { id: 'brain-noise', section: 11, statement: 'Below about 100 Hz the signal-to-noise ratio of scalp recordings depends practically only on background activity generated by the cortex; amplifier noise and the thermal noise of the interelectrode resistance dominate only at a few hundred hertz and above (measured with a high-resolution EEG setup). The background can be modeled as randomly distributed cortical dipoles in a spherical head, giving a spatial covariance that depends on electrode distance (the alpha rhythm itself is better described by a fixed dipole), and measured background is well fitted by such distance-dependent covariance models.', refs: ['scheer2006', 'demunck1992', 'huizenga2002'], status: 'verified', note: 'Audit (batch 14): supported from the three abstracts; wording narrowed to the sources’ conditions.' },
  { id: 'evoked-channels', section: 11, statement: 'Evoked responses: a P300 speller gained nothing significant from 13 electrodes added to a set of 6, and more than 8 electrodes gave small gains or losses depending on the classifier; flicker (frequency and phase) decoding no longer differed between 9 and 66 parieto-occipital electrodes once more than 0.2 s of data was used, while decoding where the user fixated kept gaining up to 66; over occipital cortex, four-class visual-category decoding rose from 57% with about 9 electrodes to 73% with 464 (4 subjects); in simulations the minimum-norm source-localization error fell from 27 mm with 32 channels to 21, 20 and 18 mm with 64, 128 and 256 (whole-head montages), the last step called modest.', refs: ['krusienski2008', 'hoffmann2008', 'ming2026', 'schreiner2026', 'song2015'], status: 'verified', note: 'Corrected after audit (batch 15): the localization errors are the minimum-norm values of a simulation (another inverse method in the same table gives far smaller errors); all other numbers confirmed in the full texts.' },
  { id: 'mi-channels', section: 11, statement: 'Motor-imagery decoders peak with 10 to 50 well-placed channels: in 80 users recorded with 119 channels the best of 13 fixed montages had 48 channels, and montages of 8 to 32 were not significantly worse when few training trials were available; on a 118-channel dataset a mean of 22.6 selected channels scored 82.3% against 73.6% with all 118; predicted error stayed at 3–4% from 52 channels down to about 14; a review relays that the number can be reduced to 10 to 20 without significant loss.', range: [10, 50], refs: ['sannelli2010', 'arvaneh2011', 'popescu2007', 'blankertz2008'], status: 'verified', note: 'Audit (batch 15): supported; Sannelli checked from its abstract, Popescu’s values read from its Figure 2a (about 4% at 14 channels), Blankertz 2008 relays another study.' },
  { id: 'calibration-cost', section: 11, statement: 'A decoder that learns its spatial weights needs the channel covariance, which is hard to estimate in high-dimensional sensor spaces, so shrinkage regularization is used; for an adaptive array that estimates the noise covariance from K independent, signal-free samples of N channels, the expected output SNR relative to the optimum is (K + 2 − N)/(K + 1), so K = 2N − 3 samples give an average loss of a factor of two (3 dB). A band B hertz wide gives at most 2B independent samples per second (exactly 2B for white noise), so 2N samples take at least N/B seconds.', refs: ['blankertz2011', 'reed1974', 'shannon1949'], status: 'partially', note: 'Audit (batch 15): the formula and arithmetic are right, but the original Reed–Mallett–Brennan paper could not be opened; the formula was confirmed through a later review that cites it. The conditions (signal-free training samples; at most 2B samples per second for colored EEG) were added. Blankertz 2011 checked from its abstract.' },
  { id: 'eeg-systems', section: 11, statement: 'Electrode counts of real systems: the International 10–20 system has 21 electrode positions; research caps go up to 256 electrodes (BioSemi 16 to 256; EGI nets 32 to 256), commercial high-density systems mostly using 160 to 256 channels; ultra-high-density grids reach 1,024 channels 8.6 mm apart; consumer headsets range from a single channel (NeuroSky MindWave) to 14 (Emotiv EPOC X).', refs: ['acharya2016', 'biosemicap', 'egiges', 'lee2022', 'gtecpangolin', 'larocco2020', 'emotivepocx'], status: 'verified', note: 'Corrected after audit (batch 15): the auditor could not verify the 10–20 count in Oostenveld & Praamstra (paywalled), so it is now cited to the American Clinical Neurophysiology Society guideline (‘21 electrode positions in the 10-20 system’), checked by hand; the single-channel lower bound is cited to the low-cost headset review of claim consumer-electrodes; a stray fragment was removed from the Emotiv citation.' },
  { id: 'blink-mechanism', section: 7, statement: 'A blink’s deflection on the scalp is not a muscle signal: blink potentials arise as the eyelids slide down over the cornea, which sits at a steady potential of about +13 mV relative to the forehead, so that the lid acts like a sliding electrode short-circuiting the cornea to the scalp, and the artifact is mostly frontal; the contribution of the eye muscles, including their activity during blinking, has been called negligible. Blink artifacts seen in intracranial recordings have been described as resembling these ocular components, which arise from the corneoretinal potential and the eye’s changing conductivity rather than muscle depolarization. In magnetoencephalography (MEG), voluntary blinks produce a large slow wave lasting about 400 ms and a small burst above 30 Hz at blink onset; the authors attribute the activity around the eyes to a combination of muscle contraction and eyelid currents.', refs: ['lins1993', 'picton2000', 'plochl2012', 'kovach2011', 'bardouille2006'], status: 'verified', note: 'Corrected after audit (batch 16): no source caps the muscle share at a small burst, so the MEG result is now reported as found, and the negligible ocular-muscle contribution is attributed to Plöchl et al.; Lins, Picton and Bardouille checked from their abstracts; Kovach et al. summarize the intracranial study of Ball et al. 2009.' },
  { id: 'mi-matrix', section: 9, statement: 'Mean change of mu-band power during cued motor imagery at the three central electrodes, from nine subjects, each in their most reactive band and relative to a 1 s rest reference (percent; ± the standard deviation across subjects): left hand C3 −64.6 ± 25.2, Cz −56.8 ± 14.7, C4 −86.7 ± 9.4; right hand C3 −84.7 ± 16.8, Cz −58.3 ± 18.4, C4 −71.6 ± 18.8; foot C3 +89.3 ± 116.8, Cz −21.3 ± 65.1, C4 +112.7 ± 140.8; tongue C3 +145.2 ± 128.9, Cz +107.0 ± 66.8, C4 +133.6 ± 160.5. The authors note that C3 and C4 overlie approximately the hand representation areas.', refs: ['pfurtscheller2006'], status: 'verified', note: 'Audit (batch 18): all 24 means and standard deviations, the nine subjects, the cue and the 1 s reference confirmed in Table 1. Nuances: the most reactive band was chosen per subject, electrode and task (9 to 14 Hz); the values come from Hjorth (Laplacian) derivations on a 60-electrode grid of about 2.5 cm spacing, not bare monopolar electrodes, so they are upper bounds for a plain C3, Cz, C4 recording; the foot task was imagery of both feet; the SD is across the nine subjects.' },
  // --- the rhythms of the scalp and traveling waves (section 6; research topic 10) ---
  { id: 'rhythm-alpha', section: 6, statement: 'The alpha rhythm is 8–13 Hz, occurs during wakefulness over the posterior head with its largest amplitude over the occipital areas, is mostly below 50 µV in adults, is best seen with the eyes closed during relaxation, and is blocked or attenuated by attention (especially visual) and mental effort.', range: [8, 13], units: 'Hz', refs: ['kane2017'], status: 'verified', note: 'Audit (batch 17): supported by the glossary entry; read in full text.' },
  { id: 'rhythm-mu', section: 6, statement: 'The mu rhythm is 7–11 Hz, composed of arch-shaped waves over the central or centro-parietal scalp during wakefulness, mostly below 50 µV, and is blocked most clearly by contralateral movement, the thought of movement, readiness to move or tactile stimulation; it is reduced by self-initiated, imagined and observed movement, has spectral peaks near 10 and 20 Hz (about 10 and 21 Hz in magnetoencephalographic recordings of four subjects), and, unlike posterior alpha, is not affected by opening the eyes (its 20 Hz component is blocked by clenching the fist but not by opening the eyes).', range: [7, 11], units: 'Hz', refs: ['kane2017', 'pineda2005', 'tiihonen1989'], status: 'verified', note: 'Audit (batch 17): supported; the 7–11 Hz band is the glossary’s (Pineda uses 8–13 Hz), the eye-opening test in Tiihonen et al. concerns the 20 Hz component, as stated.' },
  { id: 'rhythm-beta', section: 6, statement: 'The beta rhythm is 14–30 Hz, most characteristically fronto-central, mostly below 30 µV; the sensorimotor (rolandic) rhythm has components at about 10 and 20 Hz, both suppressed during a thumb movement and rebounding 0.5–2.5 s after it, the 10 Hz component arising predominantly in the primary somatosensory hand cortex and the 20 Hz sources lying slightly more anterior, which Salmelin and Hari take to be motor cortex; the 20 Hz rhythm is modulated by GABAergic inhibition (benzodiazepines raise its power and lower its frequency, which a network model reproduces as an increase in GABAergic conductance).', refs: ['kane2017', 'salmelin1994', 'jensen2005'], status: 'verified', note: 'Audit (batch 17): all numbers confirmed; wording aligned to the sources (the motor-cortex location is Salmelin and Hari’s hypothesis, and the GABAergic dependence is a modulation shown with benzodiazepines plus a model result, not a demonstrated necessity).' },
  { id: 'rhythm-theta', section: 6, statement: 'Frontal midline theta (4 to under 8 Hz) is a normal variant located on the midline just anterior to the vertex, appearing during psychological stress and cognitive tasks such as problem solving, particularly in young adults; its magnetoencephalographic source lies in bilateral medial prefrontal cortex including the anterior cingulate.', refs: ['kane2017', 'ishii1999'], status: 'verified', note: 'Audit (batch 17): supported; the glossary’s headword is “fronto-central theta”, with frontal midline theta as a synonym.' },
  { id: 'gamma-scalp', section: 6, statement: 'Gamma rhythms (above 30 Hz; the glossary bounds the band at >30 to 80 Hz) are most commonly recorded with intracranial electrodes; at the scalp, neural gamma can be below 1 µV (the review citing Herrmann and Demiralp 2005), while muscle activity recorded at temporal electrodes can reach about 100 µV, with a spectrum (about 20 to 300 Hz) that covers the whole gamma band, and during complete neuromuscular blockade of two volunteers scalp EEG power above 20 Hz fell 10- to 200-fold, illustrating substantial muscle contamination under those recording conditions.', refs: ['kane2017', 'muthukumaraswamy2013', 'whitham2007'], status: 'verified', note: 'Audit (batch 17): numbers confirmed; an earlier wording that put the 100 µV “over the same band” was corrected (the review gives the muscle amplitude without a band qualifier), and the two-subject basis of the blockade result was added. Clarity review: the conclusion is now limited to those recording conditions rather than all scalp EEG above 20 Hz.' },
  { id: 'mu-vs-alpha', section: 6, statement: 'Mu and posterior alpha share the alpha band and are told apart by topography and reactivity; the amplitude of the classical alpha rhythm tends to be larger than that of mu rhythms (both mostly below 50 µV), and mu is found with scalp EEG by eye in only a minority of adults (2.9% to 14% in the early visually read EEG of 1959 and 1966), in about half to 60% by spectral or coherence analysis, and in most if not all healthy adults by independent component analysis, though all healthy adults presumably have it. The site’s sections 9 to 11 run the mu rhythm at the strength of section 7’s alpha rhythm, a modeling assumption.', refs: ['kane2017', 'pineda2005', 'niedermeyer1997', 'hobson2017'], status: 'verified', note: 'Audit (batch 18): numbers and attributions confirmed; the 2.9% study is from 1966 (Hobson and Bishop’s reference list), so “of the 1950s” was corrected; the glossary gives mu as 7–11 Hz and treats it as an alpha-band activity distinguished by topography and reactivity. The last sentence is the site’s own.' },
  { id: 'self-generated-signals', section: 6, statement: 'The scalp signals a person can produce at will without an external stimulus are the sensorimotor mu (8–12 Hz) and beta (18–26 Hz) rhythms, which people learn to control to a usable level in 3–10 hours of training and which, with weeks of further practice (22 to 68 sessions at 2 to 4 per week, three of four users with earlier one-dimensional training), gave two-dimensional cursor control from derivations centered on C3 and C4 over the left and right sensorimotor cortex, slow cortical potentials, and alpha raised by closing the eyes, which serves as an on/off switch that most adults can operate without training; P300 and flicker responses need a stimulus.', refs: ['wolpaw2002', 'wolpaw2004', 'pineda2005', 'kirkup1997'], status: 'verified', note: 'Audit (batch 18): every number is in a source; an earlier wording that tied Pineda’s 3–10 hours of training to Wolpaw and McFarland’s two-dimensional control (22 to 68 sessions, large-Laplacian derivations on a 64-electrode cap) was split as the auditor suggested.' },
  { id: 'waves-control', section: 6, statement: 'Beta traveling waves recorded with an implanted array in the motor cortex of a tetraplegic participant propagated at roughly 15–35 cm/s. Scalp EEG also reveals broader traveling-wave patterns: one study found predominantly forward alpha waves during visual stimulation and backward waves during eyes-closed rest. Head tissues spatially smooth scalp EEG, making fine spatial patterns harder to distinguish. These cited studies do not establish voluntary control of a human scalp-EEG interface using wave direction.', refs: ['takahashi2011', 'alamia2019', 'srinivasan1998ieee'], status: 'verified', note: 'Clarity review: Srinivasan et al.’s 10–12 cm figure describes inflated electrode coherence in their model, not a hard spatial-resolution limit. Removed the inference that centimeter-scale waves are therefore impossible to resolve and the unbounded claim that deliberate wave control exists only in mice. The narrowed statement was checked against these three primary sources.' },
  { id: 'dry-through-hair', section: 8, statement: 'In a 2014 comparison with wet silver/silver-chloride electrodes, dry titanium and polyurethane electrodes that reach the scalp had significantly higher impedances, still within the range of standard biosignal amplifiers, and gave biosignal quality equivalent to the wet electrodes.', refs: ['fiedler2014'], status: 'verified', note: 'Checked by hand against the abstract of Fiedler et al. (Acta IMEKO, open access), November 2026, after the citation audit asked that the older wet-electrode conclusion be qualified. Equivalence is for their recordings; performance depends on the contact, amplifier and task.' },
  { id: 'contact-area-hair', section: 8, statement: 'A dry electrode reaches the scalp through hair with pins and touches it over a small area: in one comparison the approximate contact surfaces were 3.5 mm² for a single titanium pin, 6 mm² for a 15-pin gold electrode and 85 mm² for a soft 24-pin polyurethane electrode, against 42.5 mm² for a conventional Ag/AgCl ring electrode (the pins of all three dry designs indent the scalp slightly; the areas are nominal values from the pin-tip geometry, and the actual contact varies with hair density and pressure); measured impedances of multipin and comb dry electrodes run from tens of kilohms to about 600 kΩ (under 200 kΩ on the forehead, under 600 kΩ at the occiput for one multipin design). Anterior (forehead) and mastoid positions are free of extensive, dense hair, so a flat or wave-shaped contact touches there over its face, and on a haired scalp it is the wet gel electrode that makes full contact.', refs: ['fiedler2014', 'bernhardt2020', 'liu2023', 'chi2010'], status: 'verified', note: 'Audit (batch 19): the contact areas and pin counts match Fiedler et al.’s Table 1 and the impedances Liu et al.’s table; wording aligned (the areas are nominal, the indentation is common to the three designs). The auditor could not open Bernhardt et al.; its sentence on anterior and mastoid positions was checked by hand in the open repository copy, and the gel statement now cites Chi et al.’s review.' },
  { id: 'frontal-control', section: 6, statement: 'Frontal midline theta (5–7 Hz) is generated in the dorsal anterior cingulate and adjacent medial prefrontal cortex (localized by magnetoencephalography during mental subtraction) and appears over medial frontal areas during tasks that demand mental concentration; mental arithmetic produces late-onset, sustained increases of it. Mental tasks that engage spatially distinct cortical areas, such as mental subtraction and word association (“brain-teasers”) and spatial navigation, give event-related (de)synchronization patterns distinct from motor imagery and serve as brain–computer interface classes: in a 4-class BCI (word association, mental subtraction, spatial navigation, motor imagery), 8 of 14 users reached mean accuracies of 61–72% and controlled all four classes above chance within single sessions, with performance and brain patterns stable at a follow-up ten weeks later without training, and in an offline simulation with nine end-users with disability the best-performing pairs combined a brain-teaser with a dynamic imagery task.', range: [61, 72], units: '%', refs: ['ishii2014', 'gartner2015', 'friedrich2013', 'scherer2015'], status: 'verified', note: 'Audit (batch 19): all numbers confirmed; “mental rotation”, which none of the cited sources used, was removed, and the single-session, follow-up and offline-simulation conditions added.' },
  { id: 'scp-control', section: 6, statement: 'Slow cortical potentials (SCPs), shifts of the scalp potential over seconds recorded at the vertex, can be brought under voluntary control by operant feedback training: with the Thought Translation Device, completely paralysed patients learned over months of training (more than 100 sessions) to make their SCP more positive or more negative on command within 4 s trials and used it to select letters by successive binary choices (five for a 32-symbol alphabet, a mean of about 24 trials per letter at a 20% error rate); functional MRI implicated the basal ganglia and premotor cortex in the required positivity.', refs: ['birbaumer1999', 'birbaumer2003', 'kubler1999'], status: 'partially', note: 'Audit (batch 19): the operant training, the spelling and the fMRI finding are in Birbaumer et al. 2003’s abstract; the auditor could not open the Nature letter, and an earlier wording with a spelling rate of about two characters a minute and seven trials per character (from a conference abstract) was replaced by the trial structure, training time and trials per letter the auditor read in Kübler et al. 1999.' },
  { id: 'covert-attention', section: 6, statement: 'Covert shifts of visual attention, with the eyes fixated, modulate alpha power over parieto-occipital cortex with a topography that depends on the attended direction (in one EEG study a sustained alpha increase over PO and O electrodes); the change is classifiable on single trials, with a mean accuracy of 74.6% for each participant’s best pair of six directions (8 participants), and modulation of posterior alpha by attention in two dimensions has been proposed, from magnetoencephalographic data (four directions classified up to 69%), as a control signal.', value: 74.6, units: '%', refs: ['treder2011', 'vangerven2009'], status: 'verified', note: 'Audit (batch 19): the 74.6% figure, sites and two-dimensional proposal confirmed; an earlier wording that had alpha fall over the hemisphere contralateral to the attended side was not in either source and was replaced by what Treder et al. report (a direction-specific topography of an alpha increase); van Gerven and Jensen’s study is MEG.' },
  { id: 'p300-response', section: 6, statement: 'The P300 (P3b) is a positive wave largest over the parietal midline that peaks 250 to 500 ms after an attended, infrequent stimulus. Spellers evoke it by flashing rows and columns of letters and pick the letter whose flashes give the largest response.', refs: ['polich2007', 'farwell1988'], status: 'verified', note: 'Split from the former evoked-map claim after the November 2026 citation audit, so P300 statements cite only P300 sources. Audit (batch 20) corrected the latency from “about 300 ms” to Polich’s 250 to 500 ms window and confirmed the parietal maximum, the oddball stimulus and the row/column speller.' },
  { id: 'ssvep-response', section: 6, statement: 'The steady-state visual evoked potential (SSVEP) is the response of the visual cortex to a flickering stimulus, periodic at the flicker frequency and its harmonics and largest over the occipital scalp, so looking at one of several targets flickering at different rates selects it.', refs: ['vialatte2010', 'norcia2015'], status: 'partially', note: 'Split from the former evoked-map claim after the November 2026 citation audit. The SSVEP description could not be checked against Vialatte et al.’s full text (abstract only); Norcia et al.’s open review was added for it and remains to be audited.' },
  { id: 'error-potential', section: 6, statement: 'The error-related potential is a fronto-central negativity about 50 to 100 ms after one’s own erroneous response (or 200 to 300 ms after feedback of an error) followed by a centro-parietal positivity. It can be decoded on single trials and used to correct a machine’s action.', refs: ['chavarriaga2014'], status: 'verified', note: 'Split from the former evoked-map claim after the November 2026 citation audit. Audit (batch 20) read Chavarriaga et al. in full and found the whole error-potential description supported.' },
  { id: 'rhythm-snapshot', section: 5, statement: 'In the linear, quasi-static head model, the scalp map of one fixed source is its spatial lead-field pattern multiplied by its signed moment. A simple sinusoidal moment reverses all of that source’s electrode voltages every half-cycle, passing through zero between opposite peaks. Multiple sources with different time courses can change the shape of the summed map. Voltage sign is relative to the recording reference (the electrode average in section 4); oscillation amplitude describes the size of the swings, and a sign reversal alone need not change that amplitude.', refs: ['malmivuo1995', 'hamalainen1993', 'stoica2005'], status: 'derived', note: 'Follows from the linear forward model and the definition of sinusoidal amplitude. Independent code review confirmed that section 4 currently displays fixed snapshots, not a running oscillation, and prompted limiting the fixed-shape statement to one source.' },
  { id: 'alpha-function', section: 6, statement: 'Posterior alpha usually strengthens with eye closure and changes its spatial distribution with visual attention. Alpha increases over the hemisphere processing ignored stimuli support the hypothesis that alpha helps suppress distracting input. Alpha patterns are used to study visual attention and perception, to detect eye closure for a simple switch, and to decode attended direction in experimental EEG interfaces.', refs: ['kelly2006', 'thut2006', 'kirkup1997', 'treder2011'], status: 'verified', note: 'Independent source check: Kelly’s primary study supports suppression as an interpretation, not a proven exclusive function. Thut’s alpha lateralization predicted target-detection reaction time, not detection rate. Kirkup demonstrated an eye-closure switch, which requires eye movement. Treder classified attention direction offline; this is not a claim of general online control.' },
  { id: 'theta-function', section: 6, statement: 'Frontal midline theta often increases during demanding mental work and after errors. Coordination of theta activity between frontal regions may help adjust behavior. Researchers have combined theta with other EEG features to estimate workload in defined tasks; these results do not establish a universal workload meter or a theta-only voluntary control channel.', refs: ['gartner2015', 'cavanagh2009', 'gevins1998'], status: 'verified', note: 'Independent source check confirmed arithmetic-related theta, post-error theta and synchrony related to subsequent slowing, and multivariate classification of experimentally defined working-memory load. The possible coordination mechanism is a correlational interpretation; the limitation is scoped to these studies.' },
  { id: 'theta-context', section: 6, statement: 'Theta activity occurs during early N1 sleep as well as during awake mental tasks; frequency alone does not identify one mental state.', refs: ['aesatlas2016', 'gartner2015'], status: 'partially', note: 'Independent checker confirmed the N1 theta description in the indexed caption of AES Figure 15 and awake-task theta in Gärtner. The Bookshelf page returned a browser check, so the actual atlas waveform was not inspected. The context conclusion is a synthesis of those observations.' },
  { id: 'eeg-clinical-uses', section: 6, statement: 'EEG is used clinically to help evaluate seizures and in sleep studies to classify sleep stages. Sleep staging also uses eye movements and other recorded signals.', refs: ['nindsdiagnostics', 'nhlbisleep'], status: 'verified', note: 'Independent source check confirmed seizure evaluation in NINDS and sleep-stage classification using brain activity and eye movements in NHLBI. This states established uses, not standalone diagnostic accuracy or treatment advice.' },
  { id: 'patch-regions', section: 5, statement: 'In this primer a patch is a local grouping of cortical cells treated as a source, not a fixed anatomical unit with perfect internal synchrony. A broad functional region can contain many such groups. The numbered patches, region outlines, sizes and locations in the region-to-patch illustration are schematic modeling choices; they are not a measured parcellation or a claim that a rhythm belongs exclusively to one region. The population model permits only a fraction of a patch’s currents to be in step.', refs: ['leski2013', 'buzsaki2012'], status: 'assumption', note: 'Explicit interpretation of the site’s patch model and illustrative drawing. Internal synchrony and between-source correlation are separate model properties. Neither a drawn boundary nor the number of drawn patches is an anatomical measurement.' },
  { id: 'patch-relations', section: 5, statement: 'Cortical population models admit partially correlated inputs, and the resulting extracellular contributions can have frequency-dependent correlations. Nearby neuronal membrane potentials in mouse barrel cortex were highly correlated during quiet wakefulness but less correlated during active whisking. Proximity alone therefore does not imply a fixed degree of synchrony; the relation between local activities can depend on frequency and brain state.', refs: ['leski2013', 'poulet2008'], status: 'verified', note: 'Independent checker opened Łęski’s population-model results, including intermediate correlations and frequency-dependent coherence, and Poulet’s primary abstract. These are a computational LFP study and recordings from nearby mouse neurons, not a measured correlation or fixed patch size for human scalp EEG. Weak correlation alone is not statistical independence.' },
  { id: 'patch-cancellation', section: 5, statement: 'Scalp voltages add with their signs at each recording channel. Different timing can reinforce or reduce the sum. Cortical currents with the same time course can also partly cancel because folded cortical surfaces give different source orientations and opposing lead-field contributions. Exact cancellation at one electrode need not occur at another; two equal opposite-phase sinusoids are anticorrelated rather than independent.', refs: ['irimia2012', 'malmivuo1995'], status: 'derived', note: 'Independent source check confirmed orientation-dependent cancellation of simultaneous sources in Irimia’s anatomical forward model. Timing, channel-specific weighting, and the opposite-phase example follow from linear superposition. Complete cancellation is an ideal special case, not the typical extent of cancellation in the brain.' },
  { id: 'patch-mix-demo', section: 5, statement: 'The region-to-patch illustration displays six schematic patches but plots only the signed contributions from patches 1 and 2 at one electrode. The illustrative traces use sinusoidal source time courses and equal absolute projection weights, with a fixed vertical scale. Reinforce uses matched timing and matching projection signs; Timing drifts changes relative timing; Cancel uses equal, opposite signed voltage contributions. The traces alone do not distinguish opposite source timing from opposite projection signs. Other patches and recording noise are excluded. These traces are not computed from the anatomical lead field or calibrated in microvolts.', refs: ['malmivuo1995', 'irimia2012'], status: 'assumption', note: 'Teaching examples of linear addition, not measured signals or a fitted prediction for the displayed anatomy. The perfect cancellation example applies only to the illustrated pair at the selected electrode.' },
  { id: 'surround-ers', section: 9, statement: 'When one body part moves or is imagined, the mu rhythm over its own area desynchronizes while the rhythm over other, uninvolved areas can synchronize at the same time: foot movement increased the mu rhythm over both hand areas (three subjects), and imagining a foot movement increased the hand-area mu rhythm. The pattern, named focal ERD/surround ERS, is read as one area activated while the others are deactivated or inhibited at the same time, very likely through thalamic gating, and has been proposed as a thalamo-cortical mechanism that enhances the activation of one area by inhibiting the others at the same time; in a model of thalamo-cortical networks it depends on the interaction of relay and reticular cells, with cross-talk between the sectors of the thalamic reticular nucleus that correspond to distinct sensory modules as an essential feature. It is not seen in everyone: in another study of ten people, imagining both feet desynchronized the alpha band over the hand areas as well (shown in one subject’s maps and in the group means).', refs: ['pfurtscheller1994', 'neuper2006', 'pfurtscheller2003', 'neuper2001', 'suffczynski2001', 'yi2013'], status: 'verified', note: 'Corrected after audit (batch 21): the last sentence now says what Yi et al. show (both feet, the alpha band, one subject’s maps and the group means), and the reticular cross-talk is an essential feature of the model, not its only ingredient. Checked from the five abstracts and the full text of Yi et al.' },
  { id: 'robot-arm', section: 9, statement: 'EEG-driven robots have added degrees of freedom by sequencing, by holding one fixed or by an on/off switch, rather than by more continuous signals: in a reach-and-grasp study with a robotic arm (13 subjects, 8 to 15 sessions) the arm moved in two dimensions above the table and then in one dimension down to grasp, never more than two at once, and the authors note that continuous three-dimensional arm control would need at least three independent control signals; a quadcopter was steered with two imagery signals (turning and altitude) under a constant forward command; and a robotic arm was moved in two dimensions by hand imagery and rest while foot imagery, decoded at the same time, gave a separate on/off click.', refs: ['meng2016', 'lafleur2013', 'forenzo2025'], status: 'verified', note: 'Corrected after audit (batch 21): the lead now names the three routes (only the robotic arm of Meng et al. was sequenced); the quadcopter’s forward command, not its speed, was fixed (turning slowed it); the click was decoded at the same time as the movement, and downward movement came from rest.' },
  { id: 'compound-mi', section: 9, statement: 'Modeling choice: movements imagined at the same moment change each patch’s mu power by the product of their single changes, each raised to the intensity of its imagery (their log changes add), so the matched nonlinear decoder recovers stationary imagery intensities from their mean powers in the absence of sampling noise, and the person pays nothing for combining. No study tests whether combined changes equal the product of the single ones; one plots only group-mean spectra at C3, Cz and C4: with a hand and the opposite foot imagined together, each limb’s own area kept its desynchronization, which broadened in frequency, and both hand areas desynchronized, including the one not imagined (ten people). Holding several imagined movements at once is described as often difficult for inexperienced users, and users who learned three-dimensional control needed further practice to control all three dimensions at once. The model therefore flatters movements made together.', refs: ['yi2013', 'doud2011', 'mcfarland2010'], status: 'assumption', note: 'Audit (batch 21): the evidence was corrected. Yi et al. do plot combined changes (as group-mean spectra, without testing the product rule), and both hand areas desynchronized during hand-plus-foot imagery. The modeling choice itself has no source.' },
  { id: 'tongue-areas', section: 9, statement: 'Modeling choice: the two tongue areas lose 85% of their mu power during tongue imagery, about as much as the hand area opposite an imagined hand (claim mi-matrix), and do not respond to the other movements. The sources checked give no size for it. The tongue’s representation is small and spread over both hemispheres, and real tongue movements add a glossokinetic potential; in the 1.5 s before the cue to start, tongue imagery showed a desynchronization over the motor channels in 2 of 8 subjects and a synchronization in 2 (judged by eye; two of the eight did not perform the imagery properly); imagined tongue movements activate the tongue regions of the primary motor and premotor cortex of both hemispheres in functional magnetic resonance imaging (fMRI); the robust scalp sign of tongue imagery is the rise of the hand-area mu rhythm (claim mi-matrix). The assumption is generous.', refs: ['morash2008', 'ehrsson2003'], status: 'assumption', note: 'Audit (batch 21): the counts of Morash et al. are for tongue imagery, not movement, and are preparatory changes judged by eye over motor channels; “no study gives this size” was narrowed to the sources checked. The modeling choice itself has no source.' },
  { id: 'shoulder-area', section: 9, statement: 'Modeling choice: imagined movement of the right shoulder lowers the mu power of the left hemisphere’s shoulder patch by 85%, as assumed for the tongue (claim tongue-areas), and changes no other patch, and the other four movements leave the shoulder patch unchanged. The sources checked give no measured mu response to shoulder imagery, and the shoulder is not one of the four classes of the competition data (claim mi-classes). Shoulder movements activate primary motor cortex dorsomedial to the more distal arm segments, with extensive overlap between segments.', refs: ['grafton1993'], status: 'assumption', note: 'The location is from Grafton et al. (claim motor-map); the response size and the absence of crosstalk are modeling choices, and generous ones for a patch next to the hand area.' },
  { id: 'helicopter-3d', section: 9, statement: 'Three healthy subjects, after training on one- and two-dimensional cursor tasks, flew a virtual helicopter continuously in three dimensions with motor imagery read from scalp sensorimotor rhythms: imagining the right or left hand turned it right or left, imagining both hands or resting moved it forward or back, and imagining the tongue or the feet raised or lowered it, each axis with its own control signal. They flew through as many as 11 consecutive rings in five minutes and acquired over 85% of the rings presented.', value: 3, units: 'dimensions', refs: ['doud2011'], status: 'verified', note: 'Checked by hand against the full text (abstract and methods), November 2026.' },
  { id: 'osa-3d', section: 9, statement: 'Sixteen participants moved a cursor in three dimensions by combining overt spatial attention (shifting gaze and attention toward a side, read from parietal electrodes) with left- or right-hand motor imagery (read at C3 and C4), each controlling its own axes; in an eight-target task accuracy rose from 50.9% to 58.9% over three sessions (chance 12.5%), and nine of them went on to a twelve-target task (chance 8.3%) at 29.7 bits/min.', value: 3, units: 'dimensions', refs: ['meng2018'], status: 'verified', note: 'Checked by hand against the full text (abstract, methods and results), November 2026. One of the three signals depends on where the eyes look.' },
  { id: 'tactile-four', section: 9, statement: 'Ten able-bodied participants commanded two extra robotic arms by attending to one of four vibrating pads, whose touch evokes a P300; each attention picks one of four commands, one at a time, while the participant’s own arms keep working. On the third day the reported success rate at detecting the target’s P300 in the online tests was 79.1% in the single task and 69.7% while also doing a task with their own arms. This rate measures target detection, not four-way classification accuracy, so it has no 25% chance level.', value: 4, units: 'commands', refs: ['jia2026'], status: 'verified', note: 'Checked by hand against the full text, November 2026. Four discrete commands, not four continuous axes. The November 2026 citation audit found that an earlier wording presented the rates as four-choice accuracy against 25% chance; Jia et al. define them as target P300 detection success, separate from their sustained-decoding test.' },
  { id: 'cursor-check', section: 9, statement: 'Computed here (cursorTrial in src/physics/arm.ts): the arm model’s signals run on a modeled task inspired by the 3D cursor task of McFarland et al., with eight targets at the corners of a virtual cube, the cursor starting at the center, each axis moving 20 times per second at a speed set by its control signal minus that signal’s average, and success when the cursor reaches the right corner within 15 s. With the right hand, left hand and feet as the three axes, the figure’s default noise, 400 ms windows as in the study and the ideal person, the cursor reaches the right corner in 45% of 200 trials with a median time of 5.1 s, against 56 to 93% and 1.6 to 4.9 s for the study’s four users. Without the overlap between movements it reaches it in 96%. The target size (the outer 30% of each axis), the speed (about 1.5 s to the corner for a perfect signal) and walls that stop the cursor are assumptions; the paper’s text gives none of them, and it states the time limit as 15 s in one place and 7 s in another (rerunning the model with a 7 s limit gives 27%). Agreement with the study would not independently validate the model.', value: 45, units: '%', refs: ['mcfarland2010'], status: 'derived', note: 'Task rules checked by hand against the full text (methods, results and figure captions), November 2026. Users trained for 21 to 42 three-dimensional sessions with adaptive feature weights; the model person is untrained but ideal.' },
  { id: 'typing-speed', section: 11, statement: 'In an online transcription test taken by over 168,000 volunteers, typists averaged 51.56 words per minute (SD 20.2) with an average interval between keystrokes of 238.656 ms (SD 111.6); fast typists averaged about 120 ms between keystrokes and slow typists over 480 ms.', value: 0.239, units: 's', refs: ['dhakal2018'], status: 'verified', note: 'Checked by hand against the full text (results, words per minute and inter-key intervals), November 2026.' },
  { id: 'finger-spacing', section: 11, statement: 'With sub-millimeter 7T functional MRI, the representations of the thumb and the little finger lie 6 ± 2 mm apart in primary motor cortex and 16 ± 4 mm apart in primary sensory cortex.', range: [6, 16], units: 'mm', refs: ['huber2020'], status: 'verified', note: 'Checked by hand against the bioRxiv full text (version 2) of the published paper, November 2026.' },
  { id: 'finger-neighbors', section: 11, statement: 'Assuming the five fingers are evenly spaced, neighbors such as the index and middle finger lie a quarter of the thumb-to-little distance apart: about 1.5 mm in primary motor cortex and 4 mm in primary sensory cortex (claim finger-spacing).', range: [1.5, 4], units: 'mm', refs: ['huber2020'], status: 'derived', note: 'Even spacing is an assumption; the source reports only the thumb-to-little distance.' },
  { id: 'finger-eeg', section: 11, statement: 'Twenty-one experienced users controlled robotic fingers by imagining moving individual fingers, recorded with a 128-channel cap and decoded by a deep neural network fine-tuned to each person: after one session of online training the decoder named the right finger 80.56% of the time for thumb against little finger and 60.61% for thumb, index and little finger, each trial decided by a majority vote of decisions over 1 s windows within a 3 s trial. A decoder given only the 11 channels over the hand area opposite the hand did significantly worse than one given all 128.', refs: ['ding2025'], status: 'verified', note: 'Checked by hand against the full text (abstract, methods and results), November 2026.' },
  { id: 'finger-model', section: 11, statement: 'Modeling choice for section 11: each finger’s imagery changes a region as broad as the hand patch of sections 4 and 9 (a 10 mm disc of radial dipoles on the section 3 sphere) centered on that finger’s representation, its centers the slider’s distance apart; each carries a mu rhythm at section 7’s alpha RMS strength (the sine peak divided by √2) (claim mu-vs-alpha); imagining a finger lowers its own region’s power by 50% (claim erd-depth) and leaves the other unchanged, the two rhythms varying independently; the decoder knows both scalp patterns and the noise covariance, estimates each region with the other canceled, and picks the one whose finite-window mean squared envelope magnitude fell more, subtracting known noise baselines and retaining correlated demixed noise.', refs: ['huber2020', 'ding2025'], status: 'assumption', note: 'Broader than the fingers’ own representations, chosen so that the thumb against little finger lands near the measured result; real finger imagery also shares much of its change across the whole hand area, which this model leaves out.' },
  { id: 'finger-count', section: 11, statement: 'Computed here (pairVersusElectrodes and finiteWindowPairCorrect in src/physics/control.ts, pinned in tests/control.test.ts): with the index and middle finger regions 1.5 mm apart, 1 µV of contact noise, 10 µV of brain background and one keystroke (0.24 s) to decide, the model names the right finger 51.65% of the time with 128 electrodes over the whole head and 54.76% with 100,000; with no added noise at all, the rhythm’s own fluctuation over 0.24 s still limits it to 70.14%. With the regions 16 mm apart and a 3 s window, it gives 80.99% with 128 electrodes.', value: 51.65, units: '%', refs: ['ding2025', 'dhakal2018', 'huber2020'], status: 'derived', note: 'Model results; the electrode counts cover the whole head sphere, unlike a real cap.' },
  { id: 'dof-search', section: 9, statement: 'In literature searches made for this site (November 2026) we found no report of four or more EEG control signals steered continuously at the same time: the studies found reach three (claims dof-control, helicopter-3d, osa-3d), and the four-command interface found selects one command at a time (claim tactile-four). Not finding a report does not show that none exists.', refs: ['mcfarland2010', 'doud2011', 'meng2018', 'jia2026'], status: 'unverified', note: 'A statement about our search, not a finding of any source.' },
  { id: 'cap-separates', section: 9, statement: 'Computed here (tests/arm.test.ts): in the head of section 4 (fsaverage boundary-element lead field, BioSemi-128 electrodes, average reference), against a background of independent sources of equal strength over the whole cortex, scaled to 10 µV rms per electrode, plus 1 µV of white electrode noise, the best linear estimate of each of the six motor patches of section 4 (10 mm radius) with the other five canceled keeps 58% of the squared signal-to-noise ratio it has alone for the worst patch (the shoulder area, 19 mm from the left hemisphere’s hand area, which keeps 61%) and 97% for the best (a tongue area). Before the shoulder patch was added, the worst of the other five kept 89%.', refs: [], status: 'derived', note: 'Our own computation. The background is the modeling choice of claim brain-background, and the decoder is given the patterns and the noise covariance exactly.' },
  { id: 'arm-success', section: 9, statement: 'Computed here (src/physics/arm.ts): with the figure’s defaults (a mu rhythm as strong as section 7’s alpha, read through section 11’s 64-electrode channel over 1 s windows) and the model’s ideal person, the share of 100 attempts that end with every joint straight is 90 to 98% for one joint, 24 to 30% for two, 1 to 2% for three, 1% for four and 0 to 1% for five (one joint at a time and all together); with a perfect recording, without the channel’s noise floor, it is 48 to 74% for two joints, 9 to 19% for three, 0 to 9% for four and 0 to 5% for five. At the defaults the local standard-deviation estimate of command noise at rest, before intensity bounds, is 0.66 with one joint and 1.44 to 1.45 for the hand joints with two.', refs: [], status: 'derived', note: 'Model results for this task: the tolerance, dwell and time limit and the arm are model definitions, the responses are group means, and the person uses an idealized controller. These shares are not upper bounds on human performance.' },
  { id: 'electrode-model-settings', section: 8, statement: 'Section 8 uses illustrative circuit settings, not measured scalp values for every contact: the 1 cm² reference has abraded resistance 7.5 kΩ, capacitance 25 nF and series resistance 200 Ω; the other interfaces also use 200 Ω in series. Resistance scales inversely with area and capacitance directly with area. Contact area spans 0.1–3 cm² (default 0.1; marks 0.1 and 1). The air gap spans 0.05–2 mm (default 0.06; mark 0.5). Imagery-source synchrony is set to 0.13. Input resistance spans 10 MΩ–50 TΩ (default 1 GΩ), with fixed input capacitance 20 pF. The shared input is a 2 s, 500 Hz realization with one blink at 0.4 s, Gaussian width 0.08 s (about 188 ms full width at half maximum), and inherited skin, amplifier and residual mains noise from section 7. Added current-noise density is 1 fA/√Hz. The two contact impedances differ by 50% at 60 Hz. The mains sinusoid is assigned a 10 mV peak amplitude, not the 10 mV peak-to-peak value in the common-mode literature claim. The table evaluates impedance and voltage transmission at 10 Hz; added noise excludes inherited noise, and each strip has its own vertical scale.', refs: ['chi2010', 'huigen2002', 'mettingvanrijn1990'], status: 'assumption', note: 'Explicit documentation of existing code choices. References motivate circuit ingredients and noise mechanisms, not all chosen constants. The inherited shared input already contains recording noise; it is not a pristine before-electrode voltage.' },
  { id: 'arm-response-model', section: 9, statement: 'The arm illustration assigns measured C3, C4 and Cz group-mean power changes during four imagined movements to separate cortical hand and foot patches. This is a modeling step, not a direct measurement of those patches. The tongue- and shoulder-patch responses are the separate assumptions tongue-areas and shoulder-area, and compound imagery follows compound-mi. The 128-electrode anatomical scalp map is a display; decoder channel noise is approximated using the separate 64-electrode spherical-head model.', refs: ['pfurtscheller2006', 'gramfort2013'], status: 'assumption', note: 'Documents the distinction between measured electrode responses, assigned source responses, anatomical visualization and channel-noise approximation. No claim of fitting a particular person.' },
  { id: 'arm-decoder', section: 9, statement: 'The arm model fits a nonlinear least-squares decoder to compound and graded imagery, operating on logarithmic patch powers with the noise floor included. A command of one represents the calibrated change for full-intensity imagery, not a physical joint angle; half intensity is neutral and rest gives −1. Joints move beyond a command threshold of ±0.5, at up to 45 degrees/s, and are limited to ±135 degrees. Five imagery commands are assigned, one per joint: the four competition movements and the right shoulder (claim shoulder-area).', refs: ['pfurtscheller2006'], status: 'assumption', note: 'Task and decoder definitions in src/physics/arm.ts. The five-command set is chosen for the illustration and is not a proven biological maximum.' },
  { id: 'arm-controller', section: 9, statement: 'The simulated person has exact knowledge of the arm and signal delays and forecasts their effects. Imagery strength follows the gap from the desired joint angle, with updates five times/s. The controller closes gaps using a 0.5 s gain time, ignores gaps below 3 degrees, and varies one imagery intensity at a time in sequential mode while the others stay at half intensity (neutral). Imagery above or below half intensity drives opposite directions, allowing correction after overshoot. Combining imagery adds no control cost beyond the assumed compound source response.', refs: ['pfurtscheller2006'], status: 'assumption', note: 'An idealized controller defined in src/physics/arm.ts, not measured human skill. Source references motivate the imagery tasks, not the selected control law.' },
  { id: 'arm-task', section: 9, statement: 'The simulated arm starts folded by 60, 90, 90, 90 and 90 degrees in alternating directions. The desired arm straightens each joint over 3 s in sequential mode, or all selected joints over 4 s together. Success requires every selected joint to stay within 15 degrees of straight for 0.5 s, with a 4 s grace period after the intended movement finishes. The display compares 100 reproducible noise realizations using fixed random seeds. The window slider spans 0.5–4 s and defaults to 1 s.', refs: ['pfurtscheller2006'], status: 'assumption', note: 'Task definitions and reproducibility settings in src/physics/arm.ts and src/sections/s09-dimensions.ts. These choices define the reported simulated success rates; they are not a human performance test.' },
  { id: 'delay-model', section: 10, statement: 'Section 10 uses a steady 10 Hz rhythm in the section 7 noise model, without blinks and with skin noise set to 1 µV rms. It uses one fixed noise realization. Rhythm strength is set to section 7’s alpha example as an optimistic mu assumption. Default power loss is 50%, onset is 0.3 s after the modeled intention, and the amplitude ramp lasts 0.7 s. These onset and ramp settings are chosen using cued-imagery evidence; the cue-to-response timing does not directly measure a delay from a private intention. The decoder filters 8–13 Hz, averages squared voltage over a trailing window, and fires at the first downward threshold crossing after intention. The threshold is halfway between expected resting and fully suppressed total band power, including noise. Readout times are cumulative from intention. Slider ranges of 0.4–3 s for the window, 40–90% for power loss, 0–1.5 s for onset and 0.1–2 s for the ramp are model exploration choices.', refs: ['pfurtscheller2010', 'pfurtscheller1997', 'stoica2005'], status: 'assumption', note: 'Documents existing code and chosen exploration ranges. Does not establish a universal minimum typing time. The model omits spontaneous rhythm-amplitude fluctuations to isolate timing.' },
  { id: 'patch-map-model', section: 4, statement: 'Section 4 illustrates six representative motor patches: one hand patch in each hemisphere, one midline foot patch, one tongue patch in each hemisphere and a right-shoulder patch in the left hemisphere. These are source-model placements, not measured boundaries or complete functional regions. The default is N = 200,000 contributing cells, fraction in step 0.1 and radius 10 mm, shared across patches. Anatomical source points inside each disc receive equal weights, normalized by the magnitude of their summed cortical-normal vectors, with a lower normalization bound of 0.2 times the source count; overlapping patches are separate sources. The fsaverage boundary-element model uses brain/skull/scalp conductivities 0.3/0.006/0.3 S/m, 5,124 source locations and BioSemi-128 electrodes with average reference. The drawing shows the upper cortex and electrodes on a fitted sphere, interpolates electrode voltage with Gaussian distance weights, and uses a fixed logarithmic opacity scale of 0.1–50 µV for the sum. Each individual patch map is scaled to its own peak.', refs: ['gramfort2013', 'mnefsaverage', 'yousry1997', 'fox2001', 'grafton1993'], status: 'assumption', note: 'Explicit code and display choices in dim-model.ts, head-view.ts and s04-blur.ts. References motivate anatomy and forward modeling, not the illustrative counts, sizes or display scaling. This does not assert a hard distance-only resolution cutoff.' },
  { id: 'noise-model-settings', section: 7, statement: 'The synthetic recording uses a 10 Hz sine with slowly modulated amplitude (multiplier 0.6 + 0.4 sin(2π·0.4t)), reference amplitude 20 µV, sample rate 500 Hz and duration 4 s. Muscle noise is produced by 20 Hz high-pass and 225 Hz low-pass filters at this sample rate, then scaled to the chosen rms. Skin noise uses a 1/f approximation and defaults to 3 µV rms. White amplifier noise is 1 µV rms. Blinks have 150 µV peak amplitude, a nominal rate of 15/min and Gaussian width 0.08 s. The chosen body mains sinusoid has 10 mV peak amplitude, not peak-to-peak, with 90 dB common-mode rejection and a 0.0001 impedance-mismatch ratio, leaving about 1.3 µV peak at 60 Hz. The realization is deterministic for the selected seed. This is a synthetic recording that includes recording noise, not brain voltage before the electrodes.', refs: ['huigen2002', 'goncharova2003', 'mettingvanrijn1990'], status: 'assumption', note: 'Settings and calculation choices in physics/noise.ts and sections/s07-noise.ts. The 20–300 Hz muscle band describes the literature; the numerical filter is restricted by the simulation sample rate. References motivate the component mechanisms, not all chosen constants or their sum.' },
  { id: 'count-model', section: 11, statement: 'The electrode-count illustration uses the section 3 spherical head with electrodes spread approximately evenly over the whole scalp sphere using a Fibonacci lattice. Its displayed spacing is the square root of scalp area divided by electrode count. At equal spacing an array restricted to one hemisphere has about half the whole-sphere electrode count. At default thicknesses the scalp radius is 9.32 cm. The source disc has radius 10 mm. The noise slider explores 0.1–20 µV rms; 1 µV marks the low end of measured contact noise, while 8 µV is the chosen dry-contact example. The 0.1 µV setting is an idealized exploration value. The window slider spans 0.25–4 s, with a chosen 1 s default. Rest and imagery are assigned equal prior probabilities. The noise-free accuracy curve removes additive electrode and brain background noise but retains random rhythm-power fluctuations. Electrode noise is modeled as white and independent between contacts; background brain sources are independent radial sources but their projected scalp voltages are correlated. These are model choices, not a claim that real caps cover the full sphere or that measured skin noise is white.', refs: ['malmivuo1995', 'demunck1992', 'kay1998'], status: 'assumption', note: 'Documents code geometry, noise and display conventions. The 10 nA·m evoked source follows the common cell-group model; the stronger mu example uses alpha-source-chain as an optimistic assumption.' },
  // ───────────── section 12: named brain states ─────────────
  { id: 'consumer-states', section: 12, statement: 'Consumer EEG products are marketed as reading mental states. A review of direct-to-consumer EEG wellness devices categorizes the wellness claims their makers publish; a scoping review of 916 studies that used consumer headsets describes a single-forehead-electrode headset whose app reports built-in “meditation” and “attention” metrics, which an independent test found poorly accurate; a test of two headsets in 10 people records the maker’s claim that the single-channel device detects “focused” and “relaxed” states, finds both devices’ attention and meditation outputs highly variable, with the 14-channel device about 9 points better on concentration and relaxation tasks and, in eye-blink recognition, the single-channel device below 50% against above 75% for the 14-channel device; a systematic review of low-cost headsets records a headband claimed to help its wearer reach deep relaxation and a headset that outputs attention and meditation parameters, with drowsiness detection as the surveyed research use; and a comparison of medical and consumer wireless systems names meditation and relaxation training and coping with anxiety or pain as the popular consumer applications. Sleep staging by a consumer headband is covered by claim sleep-scoring-agreement.', refs: ['wexler2019', 'sabio2024', 'maskeliunas2016', 'larocco2020', 'ratti2017'], status: 'verified', note: 'Audit (batch 25): the two-headset comparison was corrected to the paper’s tables; the direct-to-consumer review was read from its abstract. The site names the marketed states generically; vendor names appear only in the sources.' },
  { id: 'eyes-closed-alpha', section: 12, statement: 'Closing the eyes raises alpha power several-fold. In 50 screened-healthy young adults (2 min per condition, 16 analyzed sites) the global mean alpha power was 20.0 units with the eyes closed against 5.08 with them open, about four times, and alpha was higher with the eyes closed at every region, while the global mean theta was slightly higher with the eyes open, driven by the prefrontal sites (at central, parietal, occipital and temporal sites theta was higher with the eyes closed); in 28 students, across-scalp mean absolute delta, theta, alpha and beta were all lower with the eyes open than closed, with frontal beta higher eyes open; in 608 adults (3,229 recordings) occipital alpha relative power was lower with the eyes open than closed (model coefficient −0.22); in 40 healthy older adults (mean age 73) relative occipital alpha power was 49.1 with the eyes closed against 18.9 open, about 2.6 times. The model multiplies the power of its three alpha regions by 4 with the eyes closed, its beta region, which stands for frontal beta, by 0.8, and leaves the mu rhythm unchanged (claim rhythm-mu).', value: 4, refs: ['kan2017', 'barry2007', 'park2026', 'schumacher2020'], status: 'verified', note: 'Audit (batch 22): all numbers and attributions confirmed; the regional theta pattern and the frontal reading of the beta factor were added. The 50-adult study prints its powers in “kµV²” without explaining the unit; only the ratio is used, as unit-free. The factor 4 is the young-adult value; older adults show less.' },
  { id: 'workload-signature', section: 12, statement: 'Higher mental workload raises frontal theta and beta and lowers alpha. A 2022 meta-analysis of 24 studies (723 participants) gave Hedges’ g = 0.68 (95% CI 0.41 to 0.95) for theta, 0.50 (0.21 to 0.79) for beta and −0.25 (−0.45 to 0.04) for alpha between lower and higher workload; in 20 adults doing an n-back task, frontal theta synchronization measured against the mean power of the lowest load rose from 8.75% at low to 18.48% at medium load (1 to 2 s after each stimulus) and parietal alpha desynchronization from −5.63% to −24.44% (the first second after each stimulus), with no further change at high load; in the classic 8-subject high-density study a frontal midline theta rhythm increased and a parietocentral alpha signal decreased with memory load; spectral power features told the highest from the lowest n-back level at 80 to 90% after 2 min of data, and a model combining spectral power with event-related potentials was above chance after 2.5 s for 32 of 35 participants.', refs: ['chikhi2022', 'scharinger2017', 'gevins1997', 'brouwer2012'], status: 'verified', note: 'Audit (batch 22): the reference of the n-back percentages and the fusion-model attribution were corrected; all numbers confirmed.' },
  { id: 'focus-indices', section: 12, statement: '“Attention”, “focus” and “engagement” metrics are ratios of fast to slow band power. The engagement index beta/(alpha + theta) was chosen in 1995 because it reflected task engagement best in a closed-loop automation experiment; a 2023 review of 82 documents catalogued 37 such ratio indexes, the most used being beta/alpha, beta/(alpha + theta), beta/theta and theta/alpha. The theta/beta ratio as an attention marker rests on group differences: a meta-analysis of 9 studies (1,253 children and adolescents with ADHD, 517 without) found effect sizes of 0.75 at ages 6 to 13 and 0.62 at 6 to 18, which the authors called overestimates because the studies were heterogeneous, and which shrank over the years as the ratio rose in the groups without ADHD; it judged the ratio not a reliable diagnostic measure. During cognitive tasks alpha power falls relative to pre-task eyes-open rest, more over parieto-occipital than fronto-central sites, and about 0.15 of the baseline more during mental arithmetic than during number reading (30 participants).', refs: ['pope1995', 'marcantoni2023', 'arns2013', 'magosso2019'], status: 'verified', note: 'Audit (batch 22): the participant count of the arithmetic-against-reading comparison was corrected to 30 and the meta-analysis’ own caveat added.' },
  { id: 'drowsiness-signature', section: 12, statement: 'Drowsiness and mental fatigue raise slow activity. A 2020 meta-analysis of 21 studies of mental fatigue found overall EEG power rising with a medium effect (g = 0.68), theta (g = 1.03, 95% CI 0.79 to 1.60) and alpha (g = 0.85, 0.47 to 1.43) with large effects, delta and beta with small to moderate changes, the changes largest over central sites and the theta increase above g = 1 at frontal, central and posterior sites alike; in 35 drivers in a simulator, delta and theta activity increased significantly with fatigue, and in 40 drivers the band magnitudes averaged over 19 channels rose from the alert baseline by up to 21.1 µV (delta), 3.1 µV (theta), 1.4 µV (alpha) and 1.2 µV (beta) as group means; over a monotonous drive in 52 people, slow-to-fast ratios such as (theta + alpha)/beta rose, with beta the only band that fell significantly; and before sleep onset the alpha rhythm spreads from the back of the head toward the front.', refs: ['tran2020', 'lal2002', 'lal2002b', 'jap2009', 'degennaro2001b'], status: 'verified', note: 'Audit (batch 22): all numbers and attributions confirmed; the conference paper’s maxima are group means of 20-driver subgroups.' },
  { id: 'stress-signature', section: 12, statement: 'Acute psychosocial stress lowers alpha. A 2022 systematic review and meta-analysis found alpha power, mainly frontal, decreasing consistently (Hedges’ g = 0.6, p = 0.001; 10 of 12 articles reported significant decreases), beta tending to rise without a significant pooled effect (g = −0.31 in the review’s sign convention, p = 0.29; 6 of 8 articles reported increases, 5 of them significant) and frontal alpha asymmetry not changing consistently (g = 0.01); after a 10 min Stroop stressor and after 30 h of sleep deprivation in 30 adults, high-alpha (11 to 12 Hz) relative power fell (significantly after sleep deprivation, p = 0.059 after the Stroop test) and high-beta (23 to 36 Hz) rose, strongest anteriorly, with no significant asymmetry change.', refs: ['vanhollebeke2022', 'alonso2015'], status: 'verified', note: 'Audit (batch 23): all numbers confirmed in the open review and the author postprint; the two nuances in the counts and p values were added.' },
  { id: 'meditation-signature', section: 12, statement: 'Meditation has no universal EEG signature. In 34 older novices after a 6-week course, 15 min of mindfulness meditation against 15 min of listening to a podcast, both with eyes closed, raised theta and beta power over most regions (occipital theta 291 against 171 µV²/Hz) and alpha only at occipital and right temporal sites (329 against 300), with frontal theta and alpha unchanged; practitioners of nondirective meditation, using their usual technique, showed higher theta (largest frontal and temporal-central) and alpha (largest posterior) than in eyes-closed rest; but 16 long-term Vipassana meditators showed no overall theta or alpha change against instructed mind wandering (only a relative frontal theta increase at Fz), and 10 Theravada practitioners had lower alpha during meditation than at rest. Consumer “calm” scores (one headband, used in 11 of 16 randomized trials) most likely reward alpha and theta, and a 2025 meta-analysis of those 16 trials (763 participants) found no evidence that users modulate those targets.', refs: ['ahani2014', 'lagopoulos2009', 'cahn2010', 'amihai2014', 'treves2025'], status: 'verified', note: 'Audit (batch 23): numbers confirmed; the Cahn et al. frontal theta interaction, the Lagopoulos wording and the scope of the consumer statement were corrected at the auditor’s suggestion.' },
  { id: 'relaxation-signature', section: 12, statement: 'Deliberate relaxation has no single EEG signature. A systematic review of slow-breathing studies reports higher alpha and lower theta power than during spontaneous breathing: 22 people breathing 3 to 4 times a minute with eyes closed shifted alpha from its 10 Hz peak toward 10 to 13 Hz, and the theta decrease comes from two other studies of 15 and 58 people; a randomized comparison of a recorded relaxation technique with music after 6 weeks in 36 people found larger theta increases with the technique and suggested theta, not alpha, may be the more reliable marker; and the relaxation response in 20 novices reduced frontal beta only, with no alpha or theta change in any region.', refs: ['zaccaro2018', 'jacobs2004', 'jacobs1996'], status: 'verified', note: 'Audit (batch 23): the studies behind each direction were separated at the auditor’s suggestion; otherwise supported.' },
  { id: 'valence-asymmetry', section: 12, statement: 'Emotional valence is read from frontal alpha asymmetry, the log alpha power on the right (F4) minus the left (F3), and its state effects are small. In 33 students watching four emotional film clips, baseline-normalized alpha at F3 and F4 differed between emotions by about 0.1 against between-person standard deviations of about 0.3, and alpha was higher at F4 than at F3 for positive and negative clips alike; in the 32-participant DEAP dataset no alpha electrode correlated with valence ratings at p < 0.01 (mean correlations seldom above ±0.1) and single-trial valence classification from EEG reached 57.6% against 50% for random voting (always voting the majority class reaches 58.6%, so the margin rests on the F1 score); in the original film study, disgust showed right-sided frontal and anterior temporal activation relative to happiness in epochs verified by facial expression, with no reliable difference for pooled positive against negative films. Resting asymmetry is about 60% stable trait and 40% occasion-specific state (59 people, four sessions), and its split-half reliability reaches 0.90 with about 80 s of clean data (204 people).', refs: ['zhao2018', 'koelstra2012', 'davidson1990', 'hagemann2002', 'towers2009'], status: 'verified', note: 'Audit (batch 23): supported; the DEAP majority-class baseline was added at the auditor’s suggestion.' },
  { id: 'arousal-signature', section: 12, statement: 'In the DEAP dataset (32 participants, 40 one-minute music videos), the three electrodes whose band power correlated with arousal ratings at p < 0.01 had mean within-participant correlations of only −0.06 to −0.07, individuals ranging from about −0.5 to +0.3: higher arousal went with lower theta at CP6, lower alpha at Cz and lower beta at FC2. Single-trial classification from EEG gave 62.0% for arousal and 57.6% for valence against 50% for random voting (F1 0.58 and 0.56 against a 0.5 baseline; the classes are unbalanced, so always voting the majority class would score 64.4% and 58.6%). Without any data from the test person, two-class valence reached 59.06% on DEAP and two-class positive-against-negative emotion 83.33% on SEED (chance 50%); on SEED with the same features, a three-class classifier trained on 14 people and tested on the 15th scored 56.73% (chance 33%) against about 84% within person.', value: 62, units: '%', refs: ['koelstra2012', 'li2018', 'zheng2015', 'zheng2016'], status: 'verified', note: 'Audit (batch 24): the arousal correlations, bands and sites, the majority-class baselines and the two-class SEED result were corrected to the sources’ tables.' },
  { id: 'mind-wandering-signature', section: 12, statement: 'During eyes-closed breath counting in 12 people, the 10 s before a self-caught lapse of attention showed higher theta (4 to 7 Hz) and delta (2 to 3.5 Hz) power than the 10 s after it (difference maps over the 6 s windows from −8 to −2 s and 2 to 8 s around the button press span about 0.5 to 1.2 dB across electrodes), and lower occipital alpha (9 to 11 Hz, −0.8 to −2.2 dB over −6 to −2 against 2 to 6 s) and fronto-lateral beta (15 to 30 Hz, −0.3 to −0.8 dB); half the participants reported some drowsiness.', refs: ['braboszcz2011'], status: 'verified', note: 'Audit (batch 24): numbers confirmed in the author manuscript; the decibel ranges are the limits of the figure’s color bars, now tied to their windows.' },
  { id: 'memory-retention-signature', section: 12, statement: 'While items are held in working memory, alpha and theta rise with the number of items: a 9 to 12 Hz alpha peak over posterior and central regions increased systematically with load through the last 2.5 s of a 2.8 s retention interval; frontal theta (7 to 8.5 Hz, magnetoencephalography) increased parametrically from 1 to 7 digits in 10 people; and in 69 young adults frontal-midline theta (4 to 6 Hz) rose linearly from load 2 to 5 (η² 0.05 to 0.12 for the whole sample); split by capacity, the rise was present only in the high-capacity half (η² 0.19 to 0.24) and absent in the low-capacity half.', refs: ['jensen2002', 'jensentesche2002', 'zakrzewska2014'], status: 'verified', note: 'Audit (batch 24): the participant count and the attribution of the effect sizes were corrected.' },
  { id: 'sleep-stages', section: 12, statement: 'Sleep is scored in 30 s epochs by the American Academy of Sleep Medicine rules: wake when occipital alpha (8 to 13 Hz) fills at least half the epoch, N1 when low-voltage mixed-frequency 4 to 7 Hz activity replaces it, N2 from a K complex or sleep spindle in the first half of an epoch, N3 when slow waves of 0.5 to 2 Hz and 75 µV peak-to-peak occupy more than 20% of the epoch on a frontal derivation, and REM when low-voltage mixed-frequency EEG comes with rapid eye movements and minimal chin muscle tone. Across the transition into stage 1 sleep (time series aligned to the first stage 1 epoch), power at 1 to 6 Hz rises linearly while power at 9 to 12 Hz and 16 to 28 Hz falls (26 people); across the night, non-REM sleep has more power than REM sleep from 0.25 to 16 Hz and less at 18.25 to 22 Hz.', refs: ['lambert2023', 'silber2007', 'degennaro2001', 'aeschbach1993'], status: 'verified', note: 'Audit (batch 24): confirmed; the band edge and the alignment of the sleep-onset series were made precise.' },
  { id: 'sleep-scoring-agreement', section: 12, statement: 'In the American Academy of Sleep Medicine inter-scorer reliability program, more than 2,500 scorers agreed with the majority score on 82.6% of epochs (W 84.1%, N1 63.0%, N2 85.2%, N3 67.4%, stage R the highest); experienced scorers agreed on 82.0% of epochs (Cohen’s κ 0.76) in 72 polysomnographies; a deep network scoring 30 s epochs of one raw EEG channel reached 86.2% on one public dataset and 82.0% on another; and a dry-electrode headband’s automatic staging agreed with a four-expert consensus on 83.5 ± 6.4% of epochs, against 86.4 ± 8.0% for each of five experts scored against the consensus of the other four (25 people).', refs: ['rosenberg2013', 'dankerhopfe2009', 'supratak2017', 'arnal2020'], status: 'verified', note: 'Audit (batch 24): confirmed; the headband study’s consensus is of four scorers, corrected.' },
  { id: 'anesthesia-signature', section: 12, statement: 'In 10 volunteers given slowly increasing propofol (64 channels, 2 s multitaper windows), loss of consciousness came with a rise of low-frequency (0.1 to 1 Hz) and alpha (8 to 12 Hz) power, the alpha increase concentrated frontally while a spatially coherent occipital alpha mode gave way to a frontal one; low-frequency power was more than 10-fold above baseline while unconscious, and the frontal median frequency fell from 23.1 to 12.0 Hz before loss of consciousness; a clinical review puts the amplitudes of the anesthetized signatures at 5 to 20 times those of the awake EEG. Commercial depth-of-anesthesia indices settle 14 to 155 s after an artificial change of input and 24 ± 7 to 122 ± 23 s after a change between recorded awake, anesthetized and suppressed EEG.', refs: ['purdon2013', 'purdon2015', 'pilge2006', 'zanner2009'], status: 'verified', note: 'Audit (batch 25): all numbers and attributions confirmed; the review words the factor as 5 to 20 against the awake state, the isoelectric state excepted.' },
  { id: 'state-accuracies', section: 12, statement: 'Measured accuracies of passive EEG state classifiers: two workload levels from 2 s windows, 76.1% on average within person (58.7 to 95.4%; chance 53.1% by a binomial test over 1,080 windows), 96% when 45 windows are pooled, and 3 to 4 points lower in a different affective context (21 of 24 recorded people); in a 90 min memory task a band-power chain scored 60% and drifted over the session while a probe-evoked-potential chain scored 91% (20 people); workload networks scored 87.1% on the task they were trained on and 44.8% across tasks; with no data from the test person, the best network classified two workload levels at 79.1% from 5 s windows to 86.8% from 30 s in 8 people, and the classic 1998 comparison, as that paper summarizes it, gave 83% for a group classifier against 94% for individually trained ones (the 1998 abstract itself reports better than 95% within person); with small samples, classifiers applied to pure noise reach two-class “accuracies” of 70% or more, so nominal chance understates what counts as above chance.', refs: ['muhl2014', 'roy2016', 'baldwin2012', 'hefron2018', 'gevins1998', 'combrisson2015'], status: 'verified', note: 'Audit (batch 25): the participant count and the attribution of the 1998 figures were corrected; the 1998 full text was not opened.' },
  { id: 'between-person', section: 12, statement: 'Resting band power varies widely between people: in 6,029 adults recorded with a four-channel headband (eyes closed), the standard deviation of log10 band power across people of the same age was about 0.21 to 0.36 for delta, theta, alpha and beta at AF7, AF8, TP9 and TP10, a factor of 1.6 to 2.3 in power per standard deviation and roughly two to three and a half times the spread of the age means (about 1.8 for frontal beta to 3.6 for temporoparietal alpha); log-transformed absolute power is close to normal across healthy people, though not fully so in every band, and between-person differences in eyes-closed power are largely heritable traits (760 twins and siblings). The model takes 0.65 natural-log units (0.28 log10) as the spread of each region’s resting log power between people.', value: 0.65, refs: ['hashemi2016', 'gasser1982', 'smit2005'], status: 'verified', note: 'Audit (batch 25): the ratio to the age spread and the normality statement were corrected. The standard deviations are read from the paper’s Figure 3, not printed; they include measurement noise and session-to-session change, so they bound the trait spread from above.' },
  { id: 'test-retest', section: 12, statement: 'The same person’s resting band power is stable but not fixed: over 14 days in 90 adults (64 channels, eyes open), the intraclass correlation of log10 absolute power averaged over electrodes was 0.66 for delta, 0.77 for theta, 0.88 for alpha and 0.81 for beta (relative power 0.75, 0.80, 0.86 and 0.79), with split-half consistency of absolute power within a session of 0.93 to 0.98; broad-band spectral features correlated 0.92 across 5 min and 0.84 across 12 to 16 weeks in 19 adults; posterior alpha amplitude correlated 0.72 across twelve years in 70 people. The model uses the 14-day intraclass correlations per band: the share 1 − ICC of the between-person variance changes from day to day.', refs: ['ziogas2026', 'salinsky1991', 'tenke2018'], status: 'verified', note: 'Audit (batch 25): confirmed; the intraclass correlations rest on 86 of the 90 adults after the paper’s outlier rule.' },
  { id: 'emg-beta-level', section: 12, statement: 'Muscle activity in the model: three sources at the forehead and the temples add beta-band (13 to 30 Hz) power of 5 µV rms at the scalp above each in a relaxed sitter, a level that varies between windows by a lognormal factor with log standard deviation 0.45 (a coefficient of variation of 0.49). Measured support: scalp power above 20 Hz fell 10- to 200-fold under complete neuromuscular blockade (2 people), about 5-fold at 40 Hz at central electrodes; frontalis EMG at frontal sites peaks at 20 to 30 Hz, temporalis EMG at temporal sites is broadly elevated with its maximum at 40 to 80 Hz and a smaller peak near 20 Hz, and a contraction at 15% of maximum raised the 20 to 30 Hz amplitude at Fp1 and Fp2 about 3- to 4-fold (read from the paper’s spectra) while the curves at Fz, FCz and Cz barely moved (25 adults); the coefficient of variation of beta power across 4 s epochs at rest, 0.37 to 0.49, is the range the model’s between-window spread is set to. The 5 µV level is a chosen beta-band share of section 7’s 10 µV rms relaxed muscle noise.', value: 5, units: 'µV rms', refs: ['whitham2007', 'muthukumaraswamy2013', 'goncharova2003', 'maltez2004'], status: 'assumption', note: 'Audit (batch 26): the temporalis spectrum and the spread arithmetic were corrected (the log standard deviation was lowered from 0.5 to 0.45 so the spread sits inside the measured range); the 3- to 4-fold is a reading of Figure 4.' },
  { id: 'blink-model', section: 12, statement: 'Blinks in the model: a broad source in front of the brain, below the forehead, emits section 7’s blink deflection (150 µV peak at the scalp above it, a Gaussian pulse of 0.08 s standard deviation, so about 0.3 s from base to base) 15 times a minute while the eyes are open, below the measured 17 to 23; each window’s artifact power is a Poisson sum of the pulses’ energy in each band (the shares of a Gaussian pulse’s energy below 4 Hz, at 4 to 8 Hz and at 8 to 13 Hz), so it fluctuates from window to window. Measured support: 17 blinks a minute at rest in 150 people (26 while talking, 4.5 while reading), 19.6 to 22.6 a minute with base durations of 0.29 to 0.34 s across more than 2,000 laboratory EEG datasets, blink peaks at FP1 averaging about 160 µV, an ocular contribution to frontal activity larger than the cerebral signal, inflating slow-frequency power, and shifts of power across the whole spectrum at single sites when blinks and eye movements are left in.', refs: ['bentivoglio1997', 'kleifges2017', 'guttmannflury2025', 'gasser1992', 'hagemann2001'], status: 'assumption', note: 'Audit (batch 26): every number confirmed; the pulse shape and amplitude are section 7’s (claims blink-amplitude, blink-width, blink-rate), the source’s position and 30 mm radius are modeling choices.' },
  { id: 'g-to-ratio', section: 12, statement: 'Modeling rule: where a source gives only a standardized effect size (Hedges’ g), the model takes the change of log power as 0.5 g natural-log units, a power factor of exp(0.5 g): 1.40 for g = 0.68, 1.67 for g = 1.03, 0.74 for g = −0.6. The 0.5 is a chosen within-study spread of log band power between people, below the 0.48 to 0.83 natural-log units measured across thousands of users of one headband (claim between-person), since meta-analyses standardize by spreads that include less measurement noise; the rule is approximate.', refs: ['hashemi2016'], status: 'assumption', note: 'Audit (batch 27): arithmetic confirmed; the rule assumes each g is standardized by the between-person spread of log power, so where a study standardizes by the spread of paired differences the implied change is smaller.' },
  { id: 'cap-lattice', section: 12, statement: 'Modeling choice: the N electrodes are the first N of a fixed sequence on the upper part of the section 3 head sphere, within 80° of the vertex: the vertex first, then each next electrode at the grid position (2.5° rings) farthest from every electrode already placed, ties going to the position nearest the vertex, then on the midline (face before back), then nearest the face, then on the left. The first five sit at the vertex and at the front, back, left and right of the rim, like Cz, Fpz, Oz, T7 and T8; the next are rear and front diagonal pairs about 50° from the vertex, a parietal midline site and the two central sites, like P3, P4, F3, F4, Pz, C3 and C4. The sequence is nested, so a larger array contains the smaller one and never reads worse, and the spacing stays close to the square root of the area per electrode. Where the first few electrodes sit decides what they see; real one-channel and headband devices sit on the forehead and at the ears (claim consumer-electrodes).', refs: [], status: 'assumption', note: 'Audit (batch 27): the positions of electrodes 6 to 12 were corrected to the code’s angles; the lateral rim pair sits 6° forward of the ear plane, a tie-break artifact.' },
  { id: 'state-table', section: 12, statement: 'The model’s named states as power factors relative to eyes-open rest, at its eight regions (slow waves, frontal theta, posterior alpha, left and right mu, left and right frontal alpha, beta): eyes closed ×4 alpha, ×0.8 beta (claim eyes-closed-alpha); calm with slow breathing ×1.28 alpha and ×0.78 theta (g = ±0.5 chosen for the review’s directions, claim relaxation-signature); meditating with eyes closed, the eyes-closed factors times ×1.4 theta, ×1.1 alpha, ×1.2 beta (claim meditation-signature; the theta and beta sizes chosen between its studies); drowsy ×1.67 theta, ×1.53 alpha, ×1.16 slow waves and beta (claim drowsiness-signature through claim g-to-ratio, with g = 0.3 chosen for the review’s small-to-moderate delta and beta changes); high workload ×1.40 theta, ×0.88 alpha, ×1.28 beta (claim workload-signature through g-to-ratio); focused on an easy task, half the workload changes in log terms (×1.18, ×0.94, ×1.13; the n-back study’s low load showed about half the medium load’s theta rise); stressed ×0.74 alpha, ×1.17 beta (claim stress-signature through g-to-ratio); excited ×0.94 posterior alpha and ×0.96 theta, and positive or negative mood ×0.96 left or right frontal alpha, each chosen so that the model with 32 electrodes and a 30 s window reproduces the measured single-trial accuracies of 62% for arousal and 58% for valence to within 2 points (it gives 61.5% and 56.1%; claims arousal-signature and valence-asymmetry); holding items in memory ×1.2 posterior alpha and theta (claim memory-retention-signature, size chosen); mind wandering with eyes closed, the eyes-closed factors times ×1.22 theta and slow waves, ×0.71 alpha, ×0.88 beta (the midpoints of claim mind-wandering-signature’s decibel ranges); imagined right-hand movement ×0.153 at the left-hemisphere hand area and ×0.284 at the right, imagined left-hand movement ×0.354 and ×0.133 (claim mi-matrix); light sleep N1 ×0.4 alpha, ×1.3 theta and slow waves, ×0.8 beta; N2 ×0.4 alpha, ×1.5 theta, ×3 slow waves, ×0.7 beta; deep sleep N3 ×28 slow waves (the factor at which the region’s slow waves reach the 75 µV peak-to-peak scoring criterion, 26.5 µV rms for a sine, from the 5 µV waking level), ×1.5 theta, ×0.3 alpha, ×0.5 beta and mu; REM ×0.5 alpha, ×1.2 theta, ×0.9 beta (claim sleep-stages, the other sizes chosen); anesthetized ×10 slow waves, ×8 frontal alpha, ×0.5 posterior alpha and beta, ×2 theta (claim anesthesia-signature, sizes chosen). Factors not listed are 1. Eyes-closed states have no blinks. The figure marks each state by its largest change in log terms against the rest it is defined from (eyes-open rest, or eyes-closed rest for the eyes-closed states; ties to the region with the larger resting amplitude): eyes closed, calm and holding items in memory, posterior alpha up; meditating, drowsy, focused and high workload, frontal theta up; stressed, excited, mind wandering, N1, N2 and REM, posterior alpha down; positive and negative mood, left and right frontal alpha down; the imagined hand movements, mu down at the opposite hand area; N3 and anesthetized, frontal slow waves up (pinned in tests/states.test.ts).', refs: [], status: 'assumption', note: 'Audit (batch 27): the hand factors were relabeled to the code’s hemispheres and the chosen sizes marked as such; every other factor follows from the claim named with it.' },
  { id: 'rest-amplitudes', section: 12, statement: 'Modeling choice: the root-mean-square amplitude at the scalp straight above each region at eyes-open rest is 7.1 µV for posterior alpha (section 7’s 20 µV eyes-closed alpha, 14.1 µV rms, divided by the square root of the eyes-closed factor 4), 3.5 µV for each frontal alpha region (half of that), 14.1 µV for the mu rhythm of each hand area (section 7’s alpha strength, optimistic), 4 µV for frontal midline theta, 5 µV for waking slow waves and 3.5 µV for beta. The clinical glossary gives only upper bounds: the adult alpha rhythm and the mu rhythm are mostly below 50 µV and the fronto-central beta rhythm mostly below 30 µV (peak to peak), a low-voltage waking EEG is one not above 20 µV over the whole head, and stage N3 slow waves exceed 75 µV peak to peak; it gives no amplitude for frontal midline theta, and no open normative table with explicit units was found. Beta at 3.5 µV rms is a 10 µV peak-to-peak rhythm, a third of the glossary’s bound; the theta and slow-wave levels are chosen in the same range.', refs: ['kane2017'], status: 'assumption', note: 'Audit (batch 26): the glossary bounds are verbatim (amplitudes the glossary usually measures peak to peak); the arithmetic was reproduced. The alpha chain is claim alpha-source-chain and the eyes-closed factor claim eyes-closed-alpha.' },
  { id: 'band-background', section: 12, statement: 'Modeling choice, derived: the brain’s own activity in each band at one electrode is a 15 µV rms resting EEG over 0.5 to 30 Hz, the low end of the 10 to 100 µV scalp EEG (claim eeg-amplitude), apportioned by a 1/f^1.35 spectrum: 12.4 µV rms below 4 Hz, 5.5 µV at 4 to 8 Hz, 4.2 µV at 8 to 13 Hz and 4.9 µV at 13 to 30 Hz. Measured aperiodic exponents of the resting scalp spectrum are 1.23 (SD 0.26) at frontal sites in 268 adults aged 36 to 84 (2 to 40 Hz) and 1.49 (SD 0.17) averaged over 32 channels in 46 adults with eyes open (1 to 50 Hz). The spatial correlation of the background is section 11’s (claim brain-background).', value: 1.35, refs: ['finley2022', 'jacob2021'], status: 'derived', note: 'Audit (batch 26): arithmetic reproduced exactly; Finley’s exponent is a frontal composite collapsed across eyes open and closed, Jacob’s was recorded inside an MRI scanner; 1.35 sits at their midpoint. The arithmetic: the share of a 1/f^χ spectrum between f₁ and f₂ is proportional to f₁^(1−χ) − f₂^(1−χ); 15 µV rms is a chosen total.' },
  { id: 'states-model', section: 12, statement: 'Computed here (src/physics/states.ts). Each named state is a vector of power factors at eight regions of the section 3 sphere (claim state-table). In each band the decoder estimates every region’s rhythm from the N electrodes by the minimum-mean-square (Wiener) estimate given the modeled sources’ typical powers, W = (M + Λ)⁻¹ Tᵀ C⁻¹ with M = Tᵀ C⁻¹ T the sources’ Fisher information against the band’s background and electrode noise (section 11’s model, claim snr-electrodes) and Λ the inverse typical powers; regions the cap resolves are canceled from each other’s estimates and regions it cannot resolve mix, and the artifact sources leak into the estimates with the same weights. The features are the log powers of the estimates over one window; a band-limited Gaussian process gives each power estimate a gamma distribution of shape B·T (claim erd-detect, the long-window approximation), so the features’ covariance is the trigamma of B·T (close to 1/(B·T)) times the squared normalized cross-power of the estimates, plus the lognormal spread of each source’s power between windows, days or people through its share of each estimate. Two states are separated by d′² = Δᵀ Σ⁻¹ Δ for the difference Δ of their feature means and their mean covariance Σ, and a linear decoder calls a share Φ(d′/2) of equally likely single readings correctly. States are told apart at d′ ≥ 2.56 (nine readings in ten); the named-state count is the largest pairwise told-apart set. The count of independent signals maps the box each region’s log power spans across the named states through the cap at the box’s center, whitens it by the reading covariance, and counts the principal directions along which the whitened box is at least 2.56 wide (one reading resolves 1 + extent/2.56 levels along each; the product of the levels over the directions, which an earlier version showed as “states the features could hold”, counts every combination of levels as a state and grows as a power of the window, so it is not a count of brain states and is no longer shown).', refs: ['kay1998', 'condon2016'], status: 'derived', note: 'Audit (batch 27): the five statistical results attributed were confirmed by independent algebra and Monte Carlo, and the code does what the statement says; the Gaussian treatment of log power and the linear classifier are approximations (for one region without noise the model’s accuracy is within 3 points of the exact gamma threshold rule, tests/states.test.ts), and the off-diagonal trigamma factor slightly exceeds the large-window coherence²/(B·T).' },
  { id: 'artifact-effect', section: 12, statement: 'Computed here: with the blink and muscle sources of claims blink-model and emg-beta-level left in the recording, against a decoder that cancels them, no pair of named states changes its single-reading accuracy by more than two percentage points and the named-state count changes by at most one, at every tested setting (eight electrode counts from 1 to 1,000, five windows from 1 to 60 s, all three baselines; pinned in tests/states.test.ts; the largest change found is 1.9 points). The electrodes of this layout sit away from the eyes and the muscles, the blink’s energy lies below 4 Hz where the brain’s own background is largest, and the beta changes between the named states are small, so the figure has no artifact control and leaves the artifacts in.', refs: [], status: 'derived', note: 'Audit (batch 27): the thresholds match the tests; the bound is pinned on the tested grid, and spot checks between its points found nothing above 1.5 points.' },
  { id: 'states-count', section: 12, statement: 'Computed here (src/physics/states.ts; pinned in tests/states.test.ts): with four electrodes (vertex, front, back and left rim), a 2 s window and a same-session baseline, one reading tells apart 3 of the 20 named states (eyes closed, high workload and deep sleep) and resolves 1 of the 8 regions as an independent signal (about 2.8 levels of it); with 21 electrodes 6 states and 6 signals; with 128 electrodes 7 states and the same 6 signals (six from 17 electrodes on; the principal directions coincide with the regions, and the frontal theta and beta regions stay unresolved at 2 s because their ranges across the named states are small against one reading’s scatter in those bands). A 30 s window with 128 electrodes raises the named count to 14 (15 from just above 30 s) and the resolved signals to all 8, with about 11 levels along the best direction. With no baseline (another person’s levels) the 128-electrode, 30 s count falls to 6 states and 6 signals. The far end of the slider changes little: 100,000 electrodes give the same 7 states and 6 signals as 1,000 at 2 s, and 16 states against 15 at 30 s. Reading by reading (the decoder’s feature means relative to the eyes-open state, against a bar of 2.56 standard deviations of that feature): with four electrodes and 2 s only the posterior alpha reading carries any state beyond the bar (eyes closed at ×2.59 and meditating at ×2.80 against a bar of ×2.30; the eyes-closed factor of 4 is diluted by the brain’s background); the frontal theta reading changes by at most 1.4% across the twenty states there (high workload ×1.01), and by 19% for high workload with 100,000 electrodes, against a bar of ×2.55, so no state leaves the theta bar at any electrode count with 2 s windows; with 128 electrodes and 30 s, drowsy and anesthetized do. Positive against negative mood and imagined right against left hand stay near chance at 4 electrodes.', refs: [], status: 'derived', note: 'Audit (batch 27): the named-state counts reproduced by the code and pinned by the tests. The resolved-signal counts replaced the earlier product of levels (9.9, 1,268, 2,493 and 8.2 million “cells” at the same settings, rejected as a count of states) after that audit; they are pinned in the same tests. Numbers follow the model inputs of claims state-table, rest-amplitudes and band-background; they change with any of them.' },
  // ───────────── conclusion ─────────────
  { id: 'eeg-anesthesia', section: 13, statement: 'The bispectral index (BIS) is a numerical scale computed from the EEG and used to guide the dose of general anesthetic. A Cochrane review of 52 studies (41,331 participants) found low-certainty evidence that BIS-guided anesthesia may reduce awareness during surgery compared with dosing by clinical signs (3 against 9 per 1000), with no difference against dosing by end-tidal anesthetic gas.', refs: ['lewis2019'], status: 'verified', note: 'Checked by hand against the review abstract (PubMed 31557307). Events were rare and the evidence low certainty, so the claim is that EEG monitoring is used for this, not that it is decisive.' },
  { id: 'eeg-consumer-uses', section: 13, statement: 'Consumer EEG headsets are used for meditation feedback (the Muse), sleep staging (the Dreem headband reached 83.5% agreement with polysomnography, against 86.4% for five sleep experts) and drowsiness detection. In a randomized trial of 53 novice meditators, the Muse scores did not track mindfulness, practice or improvement over a month.', refs: ['acabchuk2021', 'arnal2020', 'larocco2020'], status: 'verified', note: 'Checked by hand against the abstracts of Acabchuk et al. (Springer) and Arnal et al. (PubMed 32433768); LaRocco et al. review low-cost headsets for drowsiness detection (title and scope, read in the section 8 audit).' },
  { id: 'eeg-reach', section: 13, statement: 'EEG is used widely in clinics and research because of its low cost, non-invasive nature and pervasiveness, and one hospital archive alone, the Temple University Hospital EEG corpus, holds 16,986 recording sessions from 10,874 people.', refs: ['obeid2016'], status: 'partially', note: 'Checked by hand against the full text of Obeid & Picone. The source describes EEG as low cost, non-invasive and pervasive and gives the corpus size; the conclusion’s comparison with other neurotechnologies (“most widely distributed”) and its forecast about foundational datasets are the author’s judgment, not measured in the source.' },
  { id: 'bci-rlhf', section: 13, statement: 'Pugnet proposes replacing the button clicks of reinforcement learning from human feedback with brain signals read while an evaluator reads, such as error-related potentials, attention and cognitive load (Phase Lock part III, section 18 “BCI-RLHF”, and section 19 on alignment).', refs: ['pugnet2026'], status: 'verified', note: 'Checked by hand against the essay, November 2026. It is an opinion piece, cited for the proposal, not for evidence that it works.' },
  { id: 'errp-feedback', section: 13, statement: 'EEG error-related potentials have supplied implicit feedback that sped the learning of reinforcement-learning agents in two-dimensional navigation games, and have been decoded in real time to correct a robot’s binary object selection. Neither study evaluated language-model outputs, token-level judgments or a comparison with written feedback.', refs: ['xu2020', 'salazargomez2017'], status: 'verified', note: 'Checked by hand against the abstracts of Xu et al. (arXiv) and Salazar-Gomez et al. (MIT DSpace), November 2026. Split from bci-rlhf after the citation audit found the conclusion claimed more than these constrained demonstrations show.' },
];

export const claimById = new Map(CLAIMS.map((c) => [c.id, c]));
